      g2d = 0.0_8
      x1id = 0.0_8
      t1d = 0.0_8
      t2d = 0.0_8
      x1d = 0.0_8
      x2d = 0.0_8
      yyd = 0.0_8
      x2id = 0.0_8
      apand = 0.0_8
      scsd = 0.0_8
