      qtan2d = 0.0_8
      yyid = 0.0_8
      g1d = 0.0_8
      g2d = 0.0_8
      x1id = 0.0_8
      t1d = 0.0_8
      t2d = 0.0_8
      x1d = 0.0_8
      x2d = 0.0_8
