      psigyy = 0.5*(g1-g2)
      pgamx1d = 0.5*g1d
      pgamx1 = 0.5*g1
      pgamx2d = -(.5*g2d)
      pgamx2 = -(.5*g2)
      pgamyyd = t1d - t2d
      pgamyy = t1 - t2
