      pgamnid = x1i*pgamx1d + pgamx1*x1id + x2i*pgamx2d + pgamx2*x2id + &
&       yyi*pgamyyd + pgamyy*yyid
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
