      qtan1d = qtan1d + hopi*(sigte1*psignid+psigni*sigte1d-gamte1*&
&       pgamnid-pgamni*gamte1d)
      qtan1 = qtan1 + hopi*(psigni*sigte1-pgamni*gamte1)
      qtan2d = qtan2d + hopi*(sigte2*psignid+psigni*sigte2d-gamte2*&
&       pgamnid-pgamni*gamte2d)
      qtan2 = qtan2 + hopi*(psigni*sigte2-pgamni*gamte2)
