&             + qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
            z_qdof0 = z_qdof0 + qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&             qf0(jp))
            z_qdof1 = z_qdof1 + qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&             qf1(jp))
            z_qdof2 = z_qdof2 + qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&             qf2(jp))
            z_qdof3 = z_qdof3 + qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&             qf3(jp))
          END IF
        END IF
      END IF
    END DO
!
!
!
 110 psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
    pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
    psigx1 = -(t1-apan)
    psigx2 = t2 - apan
    psigyy = 0.5*(g1-g2)
    pgamx1 = 0.5*g1
    pgamx2 = -(.5*g2)
    pgamyy = t1 - t2
!
    psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
    pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
    sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
    sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
    gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
    gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
!
    sigte = 0.5*scs*(gam(jp)-gam(jo))
    gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
    psi = psi + hopi*(psig*sigte+pgam*gamte)
!
!---- dPsi/dGam
    dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
    dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
    dzdg(jo) = dzdg(jo) + hopi*pgam*sds*0.5
    dzdg(jp) = dzdg(jp) - hopi*pgam*sds*0.5
!
!---- dPsi/dni
    psi_ni = psi_ni + hopi*(psigni*sigte+pgamni*gamte)
!
    qtan1 = qtan1 + hopi*(psigni*sigte1+pgamni*gamte1)
    qtan2 = qtan2 + hopi*(psigni*sigte2+pgamni*gamte2)
!
    dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs-pgamni*0.5*sds)
    dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs-pgamni*0.5*sds)
!
    IF (geolin) THEN
!
!----- dPsi/dn
      dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&       sigte + hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
      dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&       sigte + hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
      z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs - hopi*&
&       pgam*0.5*(qf0(jp)-qf0(jo))*sds
      z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs - hopi*&
&       pgam*0.5*(qf1(jp)-qf1(jo))*sds
      z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs - hopi*&
&       pgam*0.5*(qf2(jp)-qf2(jo))*sds
      z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs - hopi*&
&       pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
    END IF
!
!
!**** Freestream terms
 100 psi = psi + qinf*(cosa*yi-sina*xi)
!
!---- dPsi/dn
    psi_ni = psi_ni + qinf*(cosa*nyi-sina*nxi)
!
    qtan1 = qtan1 + qinf*nyi
    qtan2 = qtan2 - qinf*nxi
!
!---- dPsi/dQinf
    z_qinf = z_qinf + (cosa*yi-sina*xi)
!
!---- dPsi/dalfa
    z_alfa = z_alfa - qinf*(sina*yi+cosa*xi)
!
    IF (.NOT.limage) THEN
      RETURN
    ELSE
!
!
!
      DO jo=1,n
        jp = jo + 1
!
        jm = jo - 1
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO &
&            99999
        END IF
!
        arg1 = (x(jo)-x(jp))**2 + (y(jo)-y(jp))**2
        dso = SQRT(arg1)
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          apan = pi - apanel(jo) + 2.0*alfa
!
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          rx1 = xi - xjo
          ry1 = yi - yjo
          rx2 = xi - xjp
          ry2 = yi - yjp
!
          sx = (xjp-xjo)*dsio
          sy = (yjp-yjo)*dsio
!
          x1 = sx*rx1 + sy*ry1
          x2 = sx*rx2 + sy*ry2
          yy = sx*ry1 - sy*rx1
!
          rs1 = rx1*rx1 + ry1*ry1
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            sgn = 1.0
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            sgn = SIGN(1.0, yy)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          g1 = LOG(rs1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          g2 = LOG(rs2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          x1i = sx*nxi + sy*nyi
          x2i = sx*nxi + sy*nyi
          yyi = sx*nyi - sy*nxi
!
          IF (geolin) THEN
            nxo = nx(jo)
            nyo = ny(jo)
            nxp = nx(jp)
            nyp = ny(jp)
!
            x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy&
&             *nyo)
            x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
            x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
            x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*&
&             nyp)
            yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*&
&             nxo)
            yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
          END IF
!
          IF (jo .EQ. n) THEN
            GOTO 120
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0 = 0.5*(x1+x2)
              rs0 = x0*x0 + yy*yy
              g0 = LOG(rs0)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              dxinv = 1.0/(x1-x0)
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*&
&               yy)*dxinv
!
              psx1 = -(t1-apan)
              psx0 = t0 - apan
              psyy = 0.5*(g1-g0)
!
              pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
              pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
              pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
              arg1 = (x(jp)-x(jm))**2 + (y(jp)-y(jm))**2
              dsm = SQRT(arg1)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
              ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
              sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              dxinv = 1.0/(x0-x2)
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*&
&               yy)*dxinv
!
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
!
              pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
              pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
              pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
              arg1 = (x(jq)-x(jo))**2 + (y(jq)-y(jo))**2
              dsp = SQRT(arg1)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            END IF
!
!------ calculate vortex panel contribution to Psi
            dxinv = 1.0/(x1-x2)
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
            psx1 = 0.5*g1
            psx2 = -(.5*g2)
            psyy = t1 - t2
!
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
            gsum1 = gamu(jp, 1) + gamu(jo, 1)
            gsum2 = gamu(jp, 2) + gamu(jo, 2)
            gdif1 = gamu(jp, 1) - gamu(jo, 1)
            gdif2 = gamu(jp, 2) - gamu(jo, 2)
!
            gsum = gam(jp) + gam(jo)
            gdif = gam(jp) - gam(jo)
!
            psi = psi - qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni - qopi*(gsum*psni+gdif*pdni)
!
            qtan1 = qtan1 - qopi*(gsum1*psni+gdif1*pdni)
            qtan2 = qtan2 - qopi*(gsum2*psni+gdif2*pdni)
!
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            IF (geolin) THEN
!
!------- dPsi/dn
              dzdn(jo) = dzdn(jo) - qopi*gsum*(psx1*x1o+psx2*x2o+psyy*&
&               yyo) - qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
              dzdn(jp) = dzdn(jp) - qopi*gsum*(psx1*x1p+psx2*x2p+psyy*&
&               yyp) - qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
              z_qdof0 = z_qdof0 - qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&               qf0(jp))
              z_qdof1 = z_qdof1 - qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&               qf1(jp))
              z_qdof2 = z_qdof2 - qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&               qf2(jp))
              z_qdof3 = z_qdof3 - qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&               qf3(jp))
            END IF
          END IF
        END IF
      END DO
!
!
!
 120  psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1 = -(t1-apan)
      psigx2 = t2 - apan
      psigyy = 0.5*(g1-g2)
      pgamx1 = 0.5*g1
      pgamx2 = -(.5*g2)
      pgamyy = t1 - t2
!
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
      sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
      sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
      gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
      gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
!
      sigte = 0.5*scs*(gam(jp)-gam(jo))
      gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
      psi = psi + hopi*(psig*sigte-pgam*gamte)
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
      psi_ni = psi_ni + hopi*(psigni*sigte-pgamni*gamte)
!
      qtan1 = qtan1 + hopi*(psigni*sigte1-pgamni*gamte1)
      qtan2 = qtan2 + hopi*(psigni*sigte2-pgamni*gamte2)
!
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      IF (geolin) THEN
!
!----- dPsi/dn
        dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&         sigte - hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
        dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&         sigte - hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
        z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs + hopi*&
&         pgam*0.5*(qf0(jp)-qf0(jo))*sds
        z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs + hopi*&
&         pgam*0.5*(qf1(jp)-qf1(jo))*sds
        z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs + hopi*&
&         pgam*0.5*(qf2(jp)-qf2(jo))*sds
        z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs + hopi*&
&         pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
      END IF
    END IF
99999 CONTINUE
  END SUBROUTINE PSILIN

!  Differentiation of psilin_xw in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: dqdm dzdm dqdg psi_ni
!   with respect to varying inputs: dqdm dste x y ante aste dzdm
!                alfa apanel dqdg gam xi yi
!*** XFOILAD: copy of PSILIN without the QTAN1/QTAN2 (GAMU) part, used by
!    XYWAKE. With the shared PSILIN, Tapenade judged GAMU inactive inside
!    XYWAKE and reset its derivative, losing the d(QINVU wake)/d(geometry)
!    contribution computed later by QWCALC.
  SUBROUTINE PSILIN_XW_D(i, xi, xid, yi, yid, nxi, nyi, psi, psi_ni, &
&   psi_nid, geolin, siglin)
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    LOGICAL :: geolin, siglin
    INTEGER :: i
    REAL :: nxi, nyi, psi, psi_ni, xi, yi
    REAL :: psi_nid, xid, yid
! intent (in) Geolin, I, Nxi, Nyi, Siglin, Xi, Yi
! intent (inout) Psi, Psi_ni
!
! Local variables
!
    REAL :: apan, dsim, dsio, dsip, dsm, dso, dsp, dxinv, g0, g1, g2, &
&   gamte1, gamte2, gdif, gdif1, gdif2, gsum, gsum1, gsum2, nxo, nxp, &
&   nyo, nyp, pdif, pdni, pdx0, pdx1, pdx2, pdyy, pgam, pgamni, pgamx1, &
&   pgamx2, pgamyy, psid, psig, psigni, psigx1, psigx2, psigyy, psis, &
&   psni, psum, psx0, psx1, psx2, psyy, qtanm, rs0, rs1, rs2, rx1, rx2, &
&   ry1, ry2, scs, sdif, sds, seps, sgn, sigte1, sigte2, ssum, sx, sy, &
&   t0, t1, t2, x0, x1, x1i, x1o, x1p, x2, x2i, x2o, x2p, xjo
    REAL :: xjp, yjo
    REAL :: apand, dsimd, dsiod, dsipd, dsmd, dsod, dspd, dxinvd, g0d, &
&   g1d, g2d, gdifd, gsumd, pdifd, pdnid, pdx0d, pdx1d, pdx2d, pdyyd, &
&   pgamnid, pgamx1d, pgamx2d, pgamyyd, psidd, psignid, psigx1d, psigx2d&
&   , psigyyd, psisd, psnid, psumd, psx0d, psx1d, psx2d, psyyd, rs0d, &
&   rs1d, rs2d, rx1d, rx2d, ry1d, ry2d, scsd, sdifd, sdsd, ssumd, sxd, &
&   syd, t0d, t1d, t2d, x0d, x1d, x1id, x2d, x2id, xjod, xjpd, yjod
    INTEGER :: io, jm, jo, jp, jq
    REAL :: yjp, yy, yyi, yyo, yyp
    REAL :: yjpd, yyd, yyid
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC SQRT
    INTRINSIC EPSILON
    INTRINSIC SIGN
    INTRINSIC LOG
    INTRINSIC ATAN2
    REAL :: arg1
    REAL :: arg1d
    REAL :: result1
    REAL :: result2
    REAL :: temp
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------------------------
!     Calculates current streamfunction Psi at panel node or wake node
!     I due to freestream and all bound vorticity Gam on the airfoil.
!     Sensitivities of Psi with respect to alpha (Z_ALFA) and inverse
!     Qspec DOFs (Z_QDOF0,Z_QDOF1) which influence Gam in inverse cases.
!     Also calculates the sensitivity vector dPsi/dGam (DZDG).
!
!     If SIGLIN=True, then Psi includes the effects of the viscous
!     source distribution Sig and the sensitivity vector dPsi/dSig
!     (DZDM) is calculated.
!
!     If GEOLIN=True, then the geometric sensitivity vector dPsi/dn
!     is calculated, where n is the normal motion of the jth node.
!
!          Airfoil:  1   < I < N
!          Wake:     N+1 < I < N+NW
!-----------------------------------------------------------------------
!
!---- distance tolerance for determining if two points are the same
    seps = (s(n)-s(1))*1.0e-5
!
    io = i
!
    cosad = -(SIN(alfa)*alfad)
    cosa = COS(alfa)
    sinad = COS(alfa)*alfad
    sina = SIN(alfa)
!
    DO jo=1,n
      dzdg(jo) = 0.0
      dzdn(jo) = 0.0
      dqdgd(jo) = 0.0_8
      dqdg(jo) = 0.0
    END DO
!
    DO jo=1,n
      dzdmd(jo) = 0.0_8
      dzdm(jo) = 0.0
      dqdmd(jo) = 0.0_8
      dqdm(jo) = 0.0
    END DO
!
    z_qinf = 0.
    z_alfa = 0.
    z_qdof0 = 0.
    z_qdof1 = 0.
    z_qdof2 = 0.
    z_qdof3 = 0.
!
    psi = 0.
    psi_ni = 0.
!
    qtanm = 0.
!
    IF (sharp) THEN
      scs = 1.0
      sds = 0.0
      psi_nid = 0.0_8
      sdsd = 0.0_8
      yyid = 0.0_8
      g1d = 0.0_8
      g2d = 0.0_8
      x1id = 0.0_8
      t1d = 0.0_8
      t2d = 0.0_8
      x2id = 0.0_8
      apand = 0.0_8
      scsd = 0.0_8
    ELSE
      scsd = (anted-ante*dsted/dste)/dste
      scs = ante/dste
      sdsd = (asted-aste*dsted/dste)/dste
      sds = aste/dste
      psi_nid = 0.0_8
      yyid = 0.0_8
      g1d = 0.0_8
      g2d = 0.0_8
      x1id = 0.0_8
      t1d = 0.0_8
      t2d = 0.0_8
      x2id = 0.0_8
      apand = 0.0_8
    END IF
!
    DO jo=1,n
      jp = jo + 1
!
      jm = jo - 1
      jq = jp + 1
!
      IF (jo .EQ. 1) THEN
        jm = jo
      ELSE IF (jo .EQ. n - 1) THEN
        jq = jp
      ELSE IF (jo .EQ. n) THEN
        jp = 1
        IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO 100
      END IF
!
      arg1d = 2*(x(jo)-x(jp))*(xd(jo)-xd(jp)) + 2*(y(jo)-y(jp))*(yd(jo)-&
&       yd(jp))
      arg1 = (x(jo)-x(jp))**2 + (y(jo)-y(jp))**2
      temp = SQRT(arg1)
      IF (arg1 .EQ. 0.0_8) THEN
        dsod = 0.0_8
      ELSE
        dsod = arg1d/(2.0*temp)
      END IF
      dso = temp
!
!------ skip null panel
! if (dso/=0.0) then 
      result1 = EPSILON(0.)
      result2 = EPSILON(0.)
      IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) THEN
!
        dsiod = -(dsod/dso**2)
        dsio = 1.0/dso
!
        apand = apaneld(jo)
        apan = apanel(jo)
!
        rx1d = xid - xd(jo)
        rx1 = xi - x(jo)
        ry1d = yid - yd(jo)
        ry1 = yi - y(jo)
        rx2d = xid - xd(jp)
        rx2 = xi - x(jp)
        ry2d = yid - yd(jp)
        ry2 = yi - y(jp)
!
        sxd = dsio*(xd(jp)-xd(jo)) + (x(jp)-x(jo))*dsiod
        sx = (x(jp)-x(jo))*dsio
        syd = dsio*(yd(jp)-yd(jo)) + (y(jp)-y(jo))*dsiod
        sy = (y(jp)-y(jo))*dsio
!
        x1d = rx1*sxd + sx*rx1d + ry1*syd + sy*ry1d
        x1 = sx*rx1 + sy*ry1
        x2d = rx2*sxd + sx*rx2d + ry2*syd + sy*ry2d
        x2 = sx*rx2 + sy*ry2
        yyd = ry1*sxd + sx*ry1d - rx1*syd - sy*rx1d
        yy = sx*ry1 - sy*rx1
!
        rs1d = 2*rx1*rx1d + 2*ry1*ry1d
        rs1 = rx1*rx1 + ry1*ry1
        rs2d = 2*rx2*rx2d + 2*ry2*ry2d
        rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
        IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
          sgn = 1.0
        ELSE
!------- make sure arctan falls between  -/+  Pi/2
          sgn = SIGN(1.0, yy)
        END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
        IF (io .NE. jo .AND. rs1 .GT. 0.0) THEN
          g1d = rs1d/rs1
          g1 = LOG(rs1)
          t1d = sgn**2*yy*x1d/((sgn*x1)**2+(sgn*yy)**2) - sgn**2*x1*yyd/&
&           ((sgn*x1)**2+(sgn*yy)**2)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g1 = 0.0
          t1 = 0.0
          g1d = 0.0_8
          t1d = 0.0_8
        END IF
!
        IF (io .NE. jp .AND. rs2 .GT. 0.0) THEN
          g2d = rs2d/rs2
          g2 = LOG(rs2)
          t2d = sgn**2*yy*x2d/((sgn*x2)**2+(sgn*yy)**2) - sgn**2*x2*yyd/&
&           ((sgn*x2)**2+(sgn*yy)**2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g2 = 0.0
          t2 = 0.0
          g2d = 0.0_8
          t2d = 0.0_8
        END IF
!
        x1id = nxi*sxd + nyi*syd
        x1i = sx*nxi + sy*nyi
        x2id = nxi*sxd + nyi*syd
        x2i = sx*nxi + sy*nyi
        yyid = nyi*sxd - nxi*syd
        yyi = sx*nyi - sy*nxi
!
        IF (geolin) THEN
          nxo = nx(jo)
          nyo = ny(jo)
          nxp = nx(jp)
          nyp = ny(jp)
!
          x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy*&
&           nyo)
          x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
          x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
          x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*nyp)
          yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*nxo)
          yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
        END IF
!
        IF (jo .EQ. n) THEN
          GOTO 110
        ELSE
!
          IF (siglin) THEN
!
!------- set up midpoint quantities
            x0d = 0.5*(x1d+x2d)
            x0 = 0.5*(x1+x2)
            rs0d = 2*x0*x0d + 2*yy*yyd
            rs0 = x0*x0 + yy*yy
            g0d = rs0d/rs0
            g0 = LOG(rs0)
            t0d = sgn**2*yy*x0d/((sgn*x0)**2+(sgn*yy)**2) - sgn**2*x0*&
&             yyd/((sgn*x0)**2+(sgn*yy)**2)
            t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
            temp = 1.0/(x1-x0)
            dxinvd = -(temp*(x1d-x0d)/(x1-x0))
            dxinv = temp
            psumd = (t0-apan)*x0d + x0*(t0d-apand) - (t1-apan)*x1d - x1*&
&             (t1d-apand) + 0.5*((g1-g0)*yyd+yy*(g1d-g0d))
            psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
            temp = (x1+x0)*psum + rs1*(t1-apan) + (x0-x1)*yy - rs0*(t0-&
&             apan)
            pdifd = dxinv*(psum*(x1d+x0d)+(x1+x0)*psumd+(t1-apan)*rs1d+&
&             rs1*(t1d-apand)+yy*(x0d-x1d)+(x0-x1)*yyd-(t0-apan)*rs0d-&
&             rs0*(t0d-apand)) + temp*dxinvd
            pdif = temp*dxinv
!
            psx1d = apand - t1d
            psx1 = -(t1-apan)
            psx0d = t0d - apand
            psx0 = t0 - apan
            psyyd = 0.5*(g1d-g0d)
            psyy = 0.5*(g1-g0)
!
            temp = (x1+x0)*psx1 + psum + 2.0*x1*(t1-apan) - pdif
            pdx1d = dxinv*(psx1*(x1d+x0d)+(x1+x0)*psx1d+psumd+2.0*((t1-&
&             apan)*x1d+x1*(t1d-apand))-pdifd) + temp*dxinvd
            pdx1 = temp*dxinv
            temp = (x1+x0)*psx0 + psum + pdif - 2.0*x0*(t0-apan)
            pdx0d = dxinv*(psx0*(x1d+x0d)+(x1+x0)*psx0d+psumd+pdifd-2.0*&
&             ((t0-apan)*x0d+x0*(t0d-apand))) + temp*dxinvd
            pdx0 = temp*dxinv
            temp = (x1+x0)*psyy + 2.0*(x0-x1+yy*(t1-t0))
            pdyyd = dxinv*(psyy*(x1d+x0d)+(x1+x0)*psyyd+2.0*(x0d-x1d+(t1&
&             -t0)*yyd+yy*(t1d-t0d))) + temp*dxinvd
            pdyy = temp*dxinv
!
            arg1d = 2*(x(jp)-x(jm))*(xd(jp)-xd(jm)) + 2*(y(jp)-y(jm))*(&
&             yd(jp)-yd(jm))
            arg1 = (x(jp)-x(jm))**2 + (y(jp)-y(jm))**2
            temp = SQRT(arg1)
            IF (arg1 .EQ. 0.0_8) THEN
              dsmd = 0.0_8
            ELSE
              dsmd = arg1d/(2.0*temp)
            END IF
            dsm = temp
            dsimd = -(dsmd/dsm**2)
            dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
            ssumd = (sig(jp)-sig(jo))*dsiod + (sig(jp)-sig(jm))*dsimd
            ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
            sdifd = (sig(jp)-sig(jo))*dsiod - (sig(jp)-sig(jm))*dsimd
            sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
            dzdmd(jm) = dzdmd(jm) + qopi*(dsim*pdifd+(pdif-psum)*dsimd-&
&             dsim*psumd)
            dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
            dzdmd(jo) = dzdmd(jo) + qopi*(-(dsio*psumd)-(psum+pdif)*&
&             dsiod-dsio*pdifd)
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
            dzdmd(jp) = dzdmd(jp) + qopi*((dsio+dsim)*psumd+psum*(dsiod+&
&             dsimd)+(dsio-dsim)*pdifd+pdif*(dsiod-dsimd))
            dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-dsim&
&             ))
!
!------- dPsi/dni
            psnid = x1i*psx1d + psx1*x1id + 0.5*((x1i+x2i)*psx0d+psx0*(&
&             x1id+x2id)) + yyi*psyyd + psyy*yyid
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            pdnid = x1i*pdx1d + pdx1*x1id + 0.5*((x1i+x2i)*pdx0d+pdx0*(&
&             x1id+x2id)) + yyi*pdyyd + pdyy*yyid
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psi_nid = psi_nid + qopi*(ssum*psnid+psni*ssumd+sdif*pdnid+&
&             pdni*sdifd)
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
            qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
            dqdmd(jm) = dqdmd(jm) + qopi*(dsim*pdnid+(pdni-psni)*dsimd-&
&             dsim*psnid)
            dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
            dqdmd(jo) = dqdmd(jo) + qopi*(-(dsio*psnid)-(psni+pdni)*&
&             dsiod-dsio*pdnid)
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
            dqdmd(jp) = dqdmd(jp) + qopi*((dsio+dsim)*psnid+psni*(dsiod+&
&             dsimd)+(dsio-dsim)*pdnid+pdni*(dsiod-dsimd))
            dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim&
&             ))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
            temp = 1.0/(x0-x2)
            dxinvd = -(temp*(x0d-x2d)/(x0-x2))
            dxinv = temp
            psumd = (t2-apan)*x2d + x2*(t2d-apand) - (t0-apan)*x0d - x0*&
&             (t0d-apand) + 0.5*((g0-g2)*yyd+yy*(g0d-g2d))
            psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
            temp = (x0+x2)*psum + rs0*(t0-apan) + (x2-x0)*yy - rs2*(t2-&
&             apan)
            pdifd = dxinv*(psum*(x0d+x2d)+(x0+x2)*psumd+(t0-apan)*rs0d+&
&             rs0*(t0d-apand)+yy*(x2d-x0d)+(x2-x0)*yyd-(t2-apan)*rs2d-&
&             rs2*(t2d-apand)) + temp*dxinvd
            pdif = temp*dxinv
!
            psx0d = apand - t0d
            psx0 = -(t0-apan)
            psx2d = t2d - apand
            psx2 = t2 - apan
            psyyd = 0.5*(g0d-g2d)
            psyy = 0.5*(g0-g2)
!
            temp = (x0+x2)*psx0 + psum + 2.0*x0*(t0-apan) - pdif
            pdx0d = dxinv*(psx0*(x0d+x2d)+(x0+x2)*psx0d+psumd+2.0*((t0-&
&             apan)*x0d+x0*(t0d-apand))-pdifd) + temp*dxinvd
            pdx0 = temp*dxinv
            temp = (x0+x2)*psx2 + psum + pdif - 2.0*x2*(t2-apan)
            pdx2d = dxinv*(psx2*(x0d+x2d)+(x0+x2)*psx2d+psumd+pdifd-2.0*&
&             ((t2-apan)*x2d+x2*(t2d-apand))) + temp*dxinvd
            pdx2 = temp*dxinv
            temp = (x0+x2)*psyy + 2.0*(x2-x0+yy*(t0-t2))
            pdyyd = dxinv*(psyy*(x0d+x2d)+(x0+x2)*psyyd+2.0*(x2d-x0d+(t0&
&             -t2)*yyd+yy*(t0d-t2d))) + temp*dxinvd
            pdyy = temp*dxinv
!
            arg1d = 2*(x(jq)-x(jo))*(xd(jq)-xd(jo)) + 2*(y(jq)-y(jo))*(&
&             yd(jq)-yd(jo))
            arg1 = (x(jq)-x(jo))**2 + (y(jq)-y(jo))**2
            temp = SQRT(arg1)
            IF (arg1 .EQ. 0.0_8) THEN
              dspd = 0.0_8
            ELSE
              dspd = arg1d/(2.0*temp)
            END IF
            dsp = temp
            dsipd = -(dspd/dsp**2)
            dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
            ssumd = (sig(jq)-sig(jo))*dsipd + (sig(jp)-sig(jo))*dsiod
            ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
            sdifd = (sig(jq)-sig(jo))*dsipd - (sig(jp)-sig(jo))*dsiod
            sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
            dzdmd(jo) = dzdmd(jo) + qopi*(-((dsip+dsio)*psumd)-psum*(&
&             dsipd+dsiod)-(dsip-dsio)*pdifd-pdif*(dsipd-dsiod))
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip-&
&             dsio))
            dzdmd(jp) = dzdmd(jp) + qopi*(dsio*psumd+(psum-pdif)*dsiod-&
&             dsio*pdifd)
            dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
            dzdmd(jq) = dzdmd(jq) + qopi*(dsip*psumd+(psum+pdif)*dsipd+&
&             dsip*pdifd)
            dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
            psnid = 0.5*((x1i+x2i)*psx0d+psx0*(x1id+x2id)) + x2i*psx2d +&
&             psx2*x2id + yyi*psyyd + psyy*yyid
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            pdnid = 0.5*((x1i+x2i)*pdx0d+pdx0*(x1id+x2id)) + x2i*pdx2d +&
&             pdx2*x2id + yyi*pdyyd + pdyy*yyid
            pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
            psi_nid = psi_nid + qopi*(ssum*psnid+psni*ssumd+sdif*pdnid+&
&             pdni*sdifd)
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
            qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
            dqdmd(jo) = dqdmd(jo) + qopi*(-((dsip+dsio)*psnid)-psni*(&
&             dsipd+dsiod)-(dsip-dsio)*pdnid-pdni*(dsipd-dsiod))
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip-&
&             dsio))
            dqdmd(jp) = dqdmd(jp) + qopi*(dsio*psnid+(psni-pdni)*dsiod-&
&             dsio*pdnid)
            dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
            dqdmd(jq) = dqdmd(jq) + qopi*(dsip*psnid+(psni+pdni)*dsipd+&
&             dsip*pdnid)
            dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
          END IF
!
!------ calculate vortex panel contribution to Psi
          temp = 1.0/(x1-x2)
          dxinvd = -(temp*(x1d-x2d)/(x1-x2))
          dxinv = temp
          psisd = 0.5*(g1*x1d+x1*g1d) - 0.5*(g2*x2d+x2*g2d) + x2d + (t1-&
&           t2)*yyd + yy*(t1d-t2d) - x1d
          psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
          temp = (x1+x2)*psis + 0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2)
          psidd = dxinv*(psis*(x1d+x2d)+(x1+x2)*psisd+0.5*(g2*rs2d+rs2*&
&           g2d-g1*rs1d-rs1*g1d+2*x1*x1d-2*x2*x2d)) + temp*dxinvd
          psid = temp*dxinv
!
          psx1d = 0.5*g1d
          psx1 = 0.5*g1
          psx2d = -(.5*g2d)
          psx2 = -(.5*g2)
          psyyd = t1d - t2d
          psyy = t1 - t2
!
          temp = (x1+x2)*psx1 + psis - x1*g1 - psid
          pdx1d = dxinv*(psx1*(x1d+x2d)+(x1+x2)*psx1d+psisd-g1*x1d-x1*&
&           g1d-psidd) + temp*dxinvd
          pdx1 = temp*dxinv
          temp = (x1+x2)*psx2 + psis + x2*g2 + psid
          pdx2d = dxinv*(psx2*(x1d+x2d)+(x1+x2)*psx2d+psisd+g2*x2d+x2*&
&           g2d+psidd) + temp*dxinvd
          pdx2 = temp*dxinv
          temp = (x1+x2)*psyy - yy*(g1-g2)
          pdyyd = dxinv*(psyy*(x1d+x2d)+(x1+x2)*psyyd-(g1-g2)*yyd-yy*(&
&           g1d-g2d)) + temp*dxinvd
          pdyy = temp*dxinv
!
!
          gsumd = gamd(jp) + gamd(jo)
          gsum = gam(jp) + gam(jo)
          gdifd = gamd(jp) - gamd(jo)
          gdif = gam(jp) - gam(jo)
!
          psi = psi + qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
          dzdg(jo) = dzdg(jo) + qopi*(psis-psid)
          dzdg(jp) = dzdg(jp) + qopi*(psis+psid)
!
!------ dPsi/dni
          psnid = x1i*psx1d + psx1*x1id + x2i*psx2d + psx2*x2id + yyi*&
&           psyyd + psyy*yyid
          psni = psx1*x1i + psx2*x2i + psyy*yyi
          pdnid = x1i*pdx1d + pdx1*x1id + x2i*pdx2d + pdx2*x2id + yyi*&
&           pdyyd + pdyy*yyid
          pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
          psi_nid = psi_nid + qopi*(psni*gsumd+gsum*psnid+pdni*gdifd+&
&           gdif*pdnid)
          psi_ni = psi_ni + qopi*(gsum*psni+gdif*pdni)
!
!
          dqdgd(jo) = dqdgd(jo) + qopi*(psnid-pdnid)
          dqdg(jo) = dqdg(jo) + qopi*(psni-pdni)
          dqdgd(jp) = dqdgd(jp) + qopi*(psnid+pdnid)
          dqdg(jp) = dqdg(jp) + qopi*(psni+pdni)
!
          IF (geolin) THEN
!
!------- dPsi/dn
            dzdn(jo) = dzdn(jo) + qopi*gsum*(psx1*x1o+psx2*x2o+psyy*yyo)&
&             + qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
            dzdn(jp) = dzdn(jp) + qopi*gsum*(psx1*x1p+psx2*x2p+psyy*yyp)&
&             + qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
            z_qdof0 = z_qdof0 + qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&             qf0(jp))
            z_qdof1 = z_qdof1 + qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&             qf1(jp))
            z_qdof2 = z_qdof2 + qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&             qf2(jp))
            z_qdof3 = z_qdof3 + qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&             qf3(jp))
          END IF
        END IF
      END IF
    END DO
!
!
!
 110 psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
    pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
    psigx1d = apand - t1d
    psigx1 = -(t1-apan)
    psigx2d = t2d - apand
    psigx2 = t2 - apan
    psigyyd = 0.5*(g1d-g2d)
    psigyy = 0.5*(g1-g2)
    pgamx1d = 0.5*g1d
    pgamx1 = 0.5*g1
    pgamx2d = -(.5*g2d)
    pgamx2 = -(.5*g2)
    pgamyyd = t1d - t2d
    pgamyy = t1 - t2
!
    psignid = x1i*psigx1d + psigx1*x1id + x2i*psigx2d + psigx2*x2id + &
&     yyi*psigyyd + psigyy*yyid
    psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
    pgamnid = x1i*pgamx1d + pgamx1*x1id + x2i*pgamx2d + pgamx2*x2id + &
&     yyi*pgamyyd + pgamyy*yyid
    pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
    sigted = 0.5*((gam(jp)-gam(jo))*scsd+scs*(gamd(jp)-gamd(jo)))
    sigte = 0.5*scs*(gam(jp)-gam(jo))
    gamted = -(.5*((gam(jp)-gam(jo))*sdsd+sds*(gamd(jp)-gamd(jo))))
    gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
    psi = psi + hopi*(psig*sigte+pgam*gamte)
!
!---- dPsi/dGam
    dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
    dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
    dzdg(jo) = dzdg(jo) + hopi*pgam*sds*0.5
    dzdg(jp) = dzdg(jp) - hopi*pgam*sds*0.5
!
!---- dPsi/dni
    psi_nid = psi_nid + hopi*(sigte*psignid+psigni*sigted+gamte*pgamnid+&
&     pgamni*gamted)
    psi_ni = psi_ni + hopi*(psigni*sigte+pgamni*gamte)
!
!
    dqdgd(jo) = dqdgd(jo) - hopi*(0.5*(scs*psignid+psigni*scsd)-0.5*(sds&
&     *pgamnid+pgamni*sdsd))
    dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs-pgamni*0.5*sds)
    dqdgd(jp) = dqdgd(jp) + hopi*(0.5*(scs*psignid+psigni*scsd)-0.5*(sds&
&     *pgamnid+pgamni*sdsd))
    dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs-pgamni*0.5*sds)
!
    IF (geolin) THEN
!
!----- dPsi/dn
      dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&       sigte + hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
      dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&       sigte + hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
      z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs - hopi*&
&       pgam*0.5*(qf0(jp)-qf0(jo))*sds
      z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs - hopi*&
&       pgam*0.5*(qf1(jp)-qf1(jo))*sds
      z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs - hopi*&
&       pgam*0.5*(qf2(jp)-qf2(jo))*sds
      z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs - hopi*&
&       pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
    END IF
!
!
!**** Freestream terms
 100 psi = psi + qinf*(cosa*yi-sina*xi)
!
!---- dPsi/dn
    psi_nid = psi_nid + qinf*(nyi*cosad-nxi*sinad)
    psi_ni = psi_ni + qinf*(cosa*nyi-sina*nxi)
!
!
!---- dPsi/dQinf
    z_qinf = z_qinf + (cosa*yi-sina*xi)
!
!---- dPsi/dalfa
    z_alfa = z_alfa - qinf*(sina*yi+cosa*xi)
!
    IF (.NOT.limage) THEN
      RETURN
    ELSE
!
!
!
      DO jo=1,n
        jp = jo + 1
!
        jm = jo - 1
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO 130
        END IF
!
        arg1d = 2*(x(jo)-x(jp))*(xd(jo)-xd(jp)) + 2*(y(jo)-y(jp))*(yd(jo&
&         )-yd(jp))
        arg1 = (x(jo)-x(jp))**2 + (y(jo)-y(jp))**2
        temp = SQRT(arg1)
        IF (arg1 .EQ. 0.0_8) THEN
          dsod = 0.0_8
        ELSE
          dsod = arg1d/(2.0*temp)
        END IF
        dso = temp
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          dsiod = -(dsod/dso**2)
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          apand = 2.0*alfad - apaneld(jo)
          apan = pi - apanel(jo) + 2.0*alfa
!
          xjod = xd(jo) + 2.0*(sina*yd(jo)+(yimage+y(jo))*sinad)
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          yjod = yd(jo) - 2.0*(cosa*yd(jo)+(yimage+y(jo))*cosad)
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          xjpd = xd(jp) + 2.0*(sina*yd(jp)+(yimage+y(jp))*sinad)
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          yjpd = yd(jp) - 2.0*(cosa*yd(jp)+(yimage+y(jp))*cosad)
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          rx1d = xid - xjod
          rx1 = xi - xjo
          ry1d = yid - yjod
          ry1 = yi - yjo
          rx2d = xid - xjpd
          rx2 = xi - xjp
          ry2d = yid - yjpd
          ry2 = yi - yjp
!
          sxd = dsio*(xjpd-xjod) + (xjp-xjo)*dsiod
          sx = (xjp-xjo)*dsio
          syd = dsio*(yjpd-yjod) + (yjp-yjo)*dsiod
          sy = (yjp-yjo)*dsio
!
          x1d = rx1*sxd + sx*rx1d + ry1*syd + sy*ry1d
          x1 = sx*rx1 + sy*ry1
          x2d = rx2*sxd + sx*rx2d + ry2*syd + sy*ry2d
          x2 = sx*rx2 + sy*ry2
          yyd = ry1*sxd + sx*ry1d - rx1*syd - sy*rx1d
          yy = sx*ry1 - sy*rx1
!
          rs1d = 2*rx1*rx1d + 2*ry1*ry1d
          rs1 = rx1*rx1 + ry1*ry1
          rs2d = 2*rx2*rx2d + 2*ry2*ry2d
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            sgn = 1.0
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            sgn = SIGN(1.0, yy)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          g1d = rs1d/rs1
          g1 = LOG(rs1)
          t1d = sgn**2*yy*x1d/((sgn*x1)**2+(sgn*yy)**2) - sgn**2*x1*yyd/&
&           ((sgn*x1)**2+(sgn*yy)**2)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          g2d = rs2d/rs2
          g2 = LOG(rs2)
          t2d = sgn**2*yy*x2d/((sgn*x2)**2+(sgn*yy)**2) - sgn**2*x2*yyd/&
&           ((sgn*x2)**2+(sgn*yy)**2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          x1id = nxi*sxd + nyi*syd
          x1i = sx*nxi + sy*nyi
          x2id = nxi*sxd + nyi*syd
          x2i = sx*nxi + sy*nyi
          yyid = nyi*sxd - nxi*syd
          yyi = sx*nyi - sy*nxi
!
          IF (geolin) THEN
            nxo = nx(jo)
            nyo = ny(jo)
            nxp = nx(jp)
            nyp = ny(jp)
!
            x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy&
&             *nyo)
            x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
            x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
            x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*&
&             nyp)
            yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*&
&             nxo)
            yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
          END IF
!
          IF (jo .EQ. n) THEN
            GOTO 120
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0d = 0.5*(x1d+x2d)
              x0 = 0.5*(x1+x2)
              rs0d = 2*x0*x0d + 2*yy*yyd
              rs0 = x0*x0 + yy*yy
              g0d = rs0d/rs0
              g0 = LOG(rs0)
              t0d = sgn**2*yy*x0d/((sgn*x0)**2+(sgn*yy)**2) - sgn**2*x0*&
&               yyd/((sgn*x0)**2+(sgn*yy)**2)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              temp = 1.0/(x1-x0)
              dxinvd = -(temp*(x1d-x0d)/(x1-x0))
              dxinv = temp
              psumd = (t0-apan)*x0d + x0*(t0d-apand) - (t1-apan)*x1d - &
&               x1*(t1d-apand) + 0.5*((g1-g0)*yyd+yy*(g1d-g0d))
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              temp = (x1+x0)*psum + rs1*(t1-apan) + (x0-x1)*yy - rs0*(t0&
&               -apan)
              pdifd = dxinv*(psum*(x1d+x0d)+(x1+x0)*psumd+(t1-apan)*rs1d&
&               +rs1*(t1d-apand)+yy*(x0d-x1d)+(x0-x1)*yyd-(t0-apan)*rs0d&
&               -rs0*(t0d-apand)) + temp*dxinvd
              pdif = temp*dxinv
!
              psx1d = apand - t1d
              psx1 = -(t1-apan)
              psx0d = t0d - apand
              psx0 = t0 - apan
              psyyd = 0.5*(g1d-g0d)
              psyy = 0.5*(g1-g0)
!
              temp = (x1+x0)*psx1 + psum + 2.0*x1*(t1-apan) - pdif
              pdx1d = dxinv*(psx1*(x1d+x0d)+(x1+x0)*psx1d+psumd+2.0*((t1&
&               -apan)*x1d+x1*(t1d-apand))-pdifd) + temp*dxinvd
              pdx1 = temp*dxinv
              temp = (x1+x0)*psx0 + psum + pdif - 2.0*x0*(t0-apan)
              pdx0d = dxinv*(psx0*(x1d+x0d)+(x1+x0)*psx0d+psumd+pdifd-&
&               2.0*((t0-apan)*x0d+x0*(t0d-apand))) + temp*dxinvd
              pdx0 = temp*dxinv
              temp = (x1+x0)*psyy + 2.0*(x0-x1+yy*(t1-t0))
              pdyyd = dxinv*(psyy*(x1d+x0d)+(x1+x0)*psyyd+2.0*(x0d-x1d+(&
&               t1-t0)*yyd+yy*(t1d-t0d))) + temp*dxinvd
              pdyy = temp*dxinv
!
              arg1d = 2*(x(jp)-x(jm))*(xd(jp)-xd(jm)) + 2*(y(jp)-y(jm))*&
&               (yd(jp)-yd(jm))
              arg1 = (x(jp)-x(jm))**2 + (y(jp)-y(jm))**2
              temp = SQRT(arg1)
              IF (arg1 .EQ. 0.0_8) THEN
                dsmd = 0.0_8
              ELSE
                dsmd = arg1d/(2.0*temp)
              END IF
              dsm = temp
              dsimd = -(dsmd/dsm**2)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
              ssumd = (sig(jp)-sig(jo))*dsiod + (sig(jp)-sig(jm))*dsimd
              ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
              sdifd = (sig(jp)-sig(jo))*dsiod - (sig(jp)-sig(jm))*dsimd
              sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdmd(jm) = dzdmd(jm) + qopi*(dsim*pdifd+(pdif-psum)*dsimd&
&               -dsim*psumd)
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdmd(jo) = dzdmd(jo) + qopi*(-(dsio*psumd)-(psum+pdif)*&
&               dsiod-dsio*pdifd)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdmd(jp) = dzdmd(jp) + qopi*((dsio+dsim)*psumd+psum*(&
&               dsiod+dsimd)+(dsio-dsim)*pdifd+pdif*(dsiod-dsimd))
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psnid = x1i*psx1d + psx1*x1id + 0.5*((x1i+x2i)*psx0d+psx0*&
&               (x1id+x2id)) + yyi*psyyd + psyy*yyid
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdnid = x1i*pdx1d + pdx1*x1id + 0.5*((x1i+x2i)*pdx0d+pdx0*&
&               (x1id+x2id)) + yyi*pdyyd + pdyy*yyid
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
              psi_nid = psi_nid + qopi*(ssum*psnid+psni*ssumd+sdif*pdnid&
&               +pdni*sdifd)
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdmd(jm) = dqdmd(jm) + qopi*(dsim*pdnid+(pdni-psni)*dsimd&
&               -dsim*psnid)
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdmd(jo) = dqdmd(jo) + qopi*(-(dsio*psnid)-(psni+pdni)*&
&               dsiod-dsio*pdnid)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdmd(jp) = dqdmd(jp) + qopi*((dsio+dsim)*psnid+psni*(&
&               dsiod+dsimd)+(dsio-dsim)*pdnid+pdni*(dsiod-dsimd))
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              temp = 1.0/(x0-x2)
              dxinvd = -(temp*(x0d-x2d)/(x0-x2))
              dxinv = temp
              psumd = (t2-apan)*x2d + x2*(t2d-apand) - (t0-apan)*x0d - &
&               x0*(t0d-apand) + 0.5*((g0-g2)*yyd+yy*(g0d-g2d))
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              temp = (x0+x2)*psum + rs0*(t0-apan) + (x2-x0)*yy - rs2*(t2&
&               -apan)
              pdifd = dxinv*(psum*(x0d+x2d)+(x0+x2)*psumd+(t0-apan)*rs0d&
&               +rs0*(t0d-apand)+yy*(x2d-x0d)+(x2-x0)*yyd-(t2-apan)*rs2d&
&               -rs2*(t2d-apand)) + temp*dxinvd
              pdif = temp*dxinv
!
              psx0d = apand - t0d
              psx0 = -(t0-apan)
              psx2d = t2d - apand
              psx2 = t2 - apan
              psyyd = 0.5*(g0d-g2d)
              psyy = 0.5*(g0-g2)
!
              temp = (x0+x2)*psx0 + psum + 2.0*x0*(t0-apan) - pdif
              pdx0d = dxinv*(psx0*(x0d+x2d)+(x0+x2)*psx0d+psumd+2.0*((t0&
&               -apan)*x0d+x0*(t0d-apand))-pdifd) + temp*dxinvd
              pdx0 = temp*dxinv
              temp = (x0+x2)*psx2 + psum + pdif - 2.0*x2*(t2-apan)
              pdx2d = dxinv*(psx2*(x0d+x2d)+(x0+x2)*psx2d+psumd+pdifd-&
&               2.0*((t2-apan)*x2d+x2*(t2d-apand))) + temp*dxinvd
              pdx2 = temp*dxinv
              temp = (x0+x2)*psyy + 2.0*(x2-x0+yy*(t0-t2))
              pdyyd = dxinv*(psyy*(x0d+x2d)+(x0+x2)*psyyd+2.0*(x2d-x0d+(&
&               t0-t2)*yyd+yy*(t0d-t2d))) + temp*dxinvd
              pdyy = temp*dxinv
!
              arg1d = 2*(x(jq)-x(jo))*(xd(jq)-xd(jo)) + 2*(y(jq)-y(jo))*&
&               (yd(jq)-yd(jo))
              arg1 = (x(jq)-x(jo))**2 + (y(jq)-y(jo))**2
              temp = SQRT(arg1)
              IF (arg1 .EQ. 0.0_8) THEN
                dspd = 0.0_8
              ELSE
                dspd = arg1d/(2.0*temp)
              END IF
              dsp = temp
              dsipd = -(dspd/dsp**2)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
              ssumd = (sig(jq)-sig(jo))*dsipd + (sig(jp)-sig(jo))*dsiod
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdifd = (sig(jq)-sig(jo))*dsipd - (sig(jp)-sig(jo))*dsiod
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdmd(jo) = dzdmd(jo) + qopi*(-((dsip+dsio)*psumd)-psum*(&
&               dsipd+dsiod)-(dsip-dsio)*pdifd-pdif*(dsipd-dsiod))
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdmd(jp) = dzdmd(jp) + qopi*(dsio*psumd+(psum-pdif)*dsiod&
&               -dsio*pdifd)
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdmd(jq) = dzdmd(jq) + qopi*(dsip*psumd+(psum+pdif)*dsipd&
&               +dsip*pdifd)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psnid = 0.5*((x1i+x2i)*psx0d+psx0*(x1id+x2id)) + x2i*psx2d&
&               + psx2*x2id + yyi*psyyd + psyy*yyid
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdnid = 0.5*((x1i+x2i)*pdx0d+pdx0*(x1id+x2id)) + x2i*pdx2d&
&               + pdx2*x2id + yyi*pdyyd + pdyy*yyid
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psi_nid = psi_nid + qopi*(ssum*psnid+psni*ssumd+sdif*pdnid&
&               +pdni*sdifd)
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdmd(jo) = dqdmd(jo) + qopi*(-((dsip+dsio)*psnid)-psni*(&
&               dsipd+dsiod)-(dsip-dsio)*pdnid-pdni*(dsipd-dsiod))
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdmd(jp) = dqdmd(jp) + qopi*(dsio*psnid+(psni-pdni)*dsiod&
&               -dsio*pdnid)
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdmd(jq) = dqdmd(jq) + qopi*(dsip*psnid+(psni+pdni)*dsipd&
&               +dsip*pdnid)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            END IF
!
!------ calculate vortex panel contribution to Psi
            temp = 1.0/(x1-x2)
            dxinvd = -(temp*(x1d-x2d)/(x1-x2))
            dxinv = temp
            psisd = 0.5*(g1*x1d+x1*g1d) - 0.5*(g2*x2d+x2*g2d) + x2d + (&
&             t1-t2)*yyd + yy*(t1d-t2d) - x1d
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            temp = (x1+x2)*psis + 0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2)
            psidd = dxinv*(psis*(x1d+x2d)+(x1+x2)*psisd+0.5*(g2*rs2d+rs2&
&             *g2d-g1*rs1d-rs1*g1d+2*x1*x1d-2*x2*x2d)) + temp*dxinvd
            psid = temp*dxinv
!
            psx1d = 0.5*g1d
            psx1 = 0.5*g1
            psx2d = -(.5*g2d)
            psx2 = -(.5*g2)
            psyyd = t1d - t2d
            psyy = t1 - t2
!
            temp = (x1+x2)*psx1 + psis - x1*g1 - psid
            pdx1d = dxinv*(psx1*(x1d+x2d)+(x1+x2)*psx1d+psisd-g1*x1d-x1*&
&             g1d-psidd) + temp*dxinvd
            pdx1 = temp*dxinv
            temp = (x1+x2)*psx2 + psis + x2*g2 + psid
            pdx2d = dxinv*(psx2*(x1d+x2d)+(x1+x2)*psx2d+psisd+g2*x2d+x2*&
&             g2d+psidd) + temp*dxinvd
            pdx2 = temp*dxinv
            temp = (x1+x2)*psyy - yy*(g1-g2)
            pdyyd = dxinv*(psyy*(x1d+x2d)+(x1+x2)*psyyd-(g1-g2)*yyd-yy*(&
&             g1d-g2d)) + temp*dxinvd
            pdyy = temp*dxinv
!
!
            gsumd = gamd(jp) + gamd(jo)
            gsum = gam(jp) + gam(jo)
            gdifd = gamd(jp) - gamd(jo)
            gdif = gam(jp) - gam(jo)
!
            psi = psi - qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psnid = x1i*psx1d + psx1*x1id + x2i*psx2d + psx2*x2id + yyi*&
&             psyyd + psyy*yyid
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdnid = x1i*pdx1d + pdx1*x1id + x2i*pdx2d + pdx2*x2id + yyi*&
&             pdyyd + pdyy*yyid
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psi_nid = psi_nid - qopi*(psni*gsumd+gsum*psnid+pdni*gdifd+&
&             gdif*pdnid)
            psi_ni = psi_ni - qopi*(gsum*psni+gdif*pdni)
!
!
            dqdgd(jo) = dqdgd(jo) - qopi*(psnid-pdnid)
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdgd(jp) = dqdgd(jp) - qopi*(psnid+pdnid)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            IF (geolin) THEN
!
!------- dPsi/dn
              dzdn(jo) = dzdn(jo) - qopi*gsum*(psx1*x1o+psx2*x2o+psyy*&
&               yyo) - qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
              dzdn(jp) = dzdn(jp) - qopi*gsum*(psx1*x1p+psx2*x2p+psyy*&
&               yyp) - qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
              z_qdof0 = z_qdof0 - qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&               qf0(jp))
              z_qdof1 = z_qdof1 - qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&               qf1(jp))
              z_qdof2 = z_qdof2 - qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&               qf2(jp))
              z_qdof3 = z_qdof3 - qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&               qf3(jp))
            END IF
          END IF
        END IF
      END DO
!
!
!
 120  psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1d = apand - t1d
      psigx1 = -(t1-apan)
      psigx2d = t2d - apand
      psigx2 = t2 - apan
      psigyyd = 0.5*(g1d-g2d)
      psigyy = 0.5*(g1-g2)
      pgamx1d = 0.5*g1d
      pgamx1 = 0.5*g1
      pgamx2d = -(.5*g2d)
      pgamx2 = -(.5*g2)
      pgamyyd = t1d - t2d
      pgamyy = t1 - t2
!
      psignid = x1i*psigx1d + psigx1*x1id + x2i*psigx2d + psigx2*x2id + &
&       yyi*psigyyd + psigyy*yyid
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamnid = x1i*pgamx1d + pgamx1*x1id + x2i*pgamx2d + pgamx2*x2id + &
&       yyi*pgamyyd + pgamyy*yyid
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
      sigted = 0.5*((gam(jp)-gam(jo))*scsd+scs*(gamd(jp)-gamd(jo)))
      sigte = 0.5*scs*(gam(jp)-gam(jo))
      gamted = -(.5*((gam(jp)-gam(jo))*sdsd+sds*(gamd(jp)-gamd(jo))))
      gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
      psi = psi + hopi*(psig*sigte-pgam*gamte)
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
      psi_nid = psi_nid + hopi*(sigte*psignid+psigni*sigted-gamte*&
&       pgamnid-pgamni*gamted)
      psi_ni = psi_ni + hopi*(psigni*sigte-pgamni*gamte)
!
!
      dqdgd(jo) = dqdgd(jo) - hopi*(0.5*(scs*psignid+psigni*scsd)+0.5*(&
&       sds*pgamnid+pgamni*sdsd))
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdgd(jp) = dqdgd(jp) + hopi*(0.5*(scs*psignid+psigni*scsd)+0.5*(&
&       sds*pgamnid+pgamni*sdsd))
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      IF (geolin) THEN
!
!----- dPsi/dn
        dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&         sigte - hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
        dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&         sigte - hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
        z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs + hopi*&
&         pgam*0.5*(qf0(jp)-qf0(jo))*sds
        z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs + hopi*&
&         pgam*0.5*(qf1(jp)-qf1(jo))*sds
        z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs + hopi*&
&         pgam*0.5*(qf2(jp)-qf2(jo))*sds
        z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs + hopi*&
&         pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
      END IF
    END IF
 130 CONTINUE
  END SUBROUTINE PSILIN_XW_D

!*** XFOILAD: copy of PSILIN without the QTAN1/QTAN2 (GAMU) part, used by
!    XYWAKE. With the shared PSILIN, Tapenade judged GAMU inactive inside
!    XYWAKE and reset its derivative, losing the d(QINVU wake)/d(geometry)
!    contribution computed later by QWCALC.
  SUBROUTINE PSILIN_XW(i, xi, yi, nxi, nyi, psi, psi_ni, geolin, siglin)
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    LOGICAL :: geolin, siglin
    INTEGER :: i
    REAL :: nxi, nyi, psi, psi_ni, xi, yi
! intent (in) Geolin, I, Nxi, Nyi, Siglin, Xi, Yi
! intent (inout) Psi, Psi_ni
!
! Local variables
!
    REAL :: apan, dsim, dsio, dsip, dsm, dso, dsp, dxinv, g0, g1, g2, &
&   gamte1, gamte2, gdif, gdif1, gdif2, gsum, gsum1, gsum2, nxo, nxp, &
&   nyo, nyp, pdif, pdni, pdx0, pdx1, pdx2, pdyy, pgam, pgamni, pgamx1, &
&   pgamx2, pgamyy, psid, psig, psigni, psigx1, psigx2, psigyy, psis, &
&   psni, psum, psx0, psx1, psx2, psyy, qtanm, rs0, rs1, rs2, rx1, rx2, &
&   ry1, ry2, scs, sdif, sds, seps, sgn, sigte1, sigte2, ssum, sx, sy, &
&   t0, t1, t2, x0, x1, x1i, x1o, x1p, x2, x2i, x2o, x2p, xjo
    REAL :: xjp, yjo
    INTEGER :: io, jm, jo, jp, jq
    REAL :: yjp, yy, yyi, yyo, yyp
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC SQRT
    INTRINSIC EPSILON
    INTRINSIC SIGN
    INTRINSIC LOG
    INTRINSIC ATAN2
    REAL :: arg1
    REAL :: result1
    REAL :: result2
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------------------------
!     Calculates current streamfunction Psi at panel node or wake node
!     I due to freestream and all bound vorticity Gam on the airfoil.
!     Sensitivities of Psi with respect to alpha (Z_ALFA) and inverse
!     Qspec DOFs (Z_QDOF0,Z_QDOF1) which influence Gam in inverse cases.
!     Also calculates the sensitivity vector dPsi/dGam (DZDG).
!
!     If SIGLIN=True, then Psi includes the effects of the viscous
!     source distribution Sig and the sensitivity vector dPsi/dSig
!     (DZDM) is calculated.
!
!     If GEOLIN=True, then the geometric sensitivity vector dPsi/dn
!     is calculated, where n is the normal motion of the jth node.
!
!          Airfoil:  1   < I < N
!          Wake:     N+1 < I < N+NW
!-----------------------------------------------------------------------
!
!---- distance tolerance for determining if two points are the same
    seps = (s(n)-s(1))*1.0e-5
!
    io = i
!
    cosa = COS(alfa)
    sina = SIN(alfa)
!
    DO jo=1,n
      dzdg(jo) = 0.0
      dzdn(jo) = 0.0
      dqdg(jo) = 0.0
    END DO
!
    DO jo=1,n
      dzdm(jo) = 0.0
      dqdm(jo) = 0.0
    END DO
!
    z_qinf = 0.
    z_alfa = 0.
    z_qdof0 = 0.
    z_qdof1 = 0.
    z_qdof2 = 0.
    z_qdof3 = 0.
!
    psi = 0.
    psi_ni = 0.
!
    qtanm = 0.
!
    IF (sharp) THEN
      scs = 1.0
      sds = 0.0
    ELSE
      scs = ante/dste
      sds = aste/dste
    END IF
!
    DO jo=1,n
      jp = jo + 1
!
      jm = jo - 1
      jq = jp + 1
!
      IF (jo .EQ. 1) THEN
        jm = jo
      ELSE IF (jo .EQ. n - 1) THEN
        jq = jp
      ELSE IF (jo .EQ. n) THEN
        jp = 1
        IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO 100
      END IF
!
      arg1 = (x(jo)-x(jp))**2 + (y(jo)-y(jp))**2
      dso = SQRT(arg1)
!
!------ skip null panel
! if (dso/=0.0) then 
      result1 = EPSILON(0.)
      result2 = EPSILON(0.)
      IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) THEN
!
        dsio = 1.0/dso
!
        apan = apanel(jo)
!
        rx1 = xi - x(jo)
        ry1 = yi - y(jo)
        rx2 = xi - x(jp)
        ry2 = yi - y(jp)
!
        sx = (x(jp)-x(jo))*dsio
        sy = (y(jp)-y(jo))*dsio
!
        x1 = sx*rx1 + sy*ry1
        x2 = sx*rx2 + sy*ry2
        yy = sx*ry1 - sy*rx1
!
        rs1 = rx1*rx1 + ry1*ry1
        rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
        IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
          sgn = 1.0
        ELSE
!------- make sure arctan falls between  -/+  Pi/2
          sgn = SIGN(1.0, yy)
        END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
        IF (io .NE. jo .AND. rs1 .GT. 0.0) THEN
          g1 = LOG(rs1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g1 = 0.0
          t1 = 0.0
        END IF
!
        IF (io .NE. jp .AND. rs2 .GT. 0.0) THEN
          g2 = LOG(rs2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g2 = 0.0
          t2 = 0.0
        END IF
!
        x1i = sx*nxi + sy*nyi
        x2i = sx*nxi + sy*nyi
        yyi = sx*nyi - sy*nxi
!
        IF (geolin) THEN
          nxo = nx(jo)
          nyo = ny(jo)
          nxp = nx(jp)
          nyp = ny(jp)
!
          x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy*&
&           nyo)
          x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
          x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
          x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*nyp)
          yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*nxo)
          yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
        END IF
!
        IF (jo .EQ. n) THEN
          GOTO 110
        ELSE
!
          IF (siglin) THEN
!
!------- set up midpoint quantities
            x0 = 0.5*(x1+x2)
            rs0 = x0*x0 + yy*yy
            g0 = LOG(rs0)
            t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
            dxinv = 1.0/(x1-x0)
            psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
            pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*yy)&
&             *dxinv
!
            psx1 = -(t1-apan)
            psx0 = t0 - apan
            psyy = 0.5*(g1-g0)
!
            pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
            pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
            pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
            arg1 = (x(jp)-x(jm))**2 + (y(jp)-y(jm))**2
            dsm = SQRT(arg1)
            dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
            ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
            sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
            dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
            dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-dsim&
&             ))
!
!------- dPsi/dni
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
            qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
            dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
            dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim&
&             ))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
            dxinv = 1.0/(x0-x2)
            psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
            pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*yy)&
&             *dxinv
!
            psx0 = -(t0-apan)
            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
!
            pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
            pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
            pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
            arg1 = (x(jq)-x(jo))**2 + (y(jq)-y(jo))**2
            dsp = SQRT(arg1)
            dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
            ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
            sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
