!
!------- dPsi/dni
      psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
      pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
      psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
      dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
      dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
      dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
      dxinv = 1.0/(x0-x2)
      psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
      pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*yy)*dxinv
!
      psx0 = -(t0-apan)
      psx2 = t2 - apan
      psyy = 0.5*(g0-g2)
!
      pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
      pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
      pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
      arg1 = (x(jq)-x(jo))**2 + (y(jq)-y(jo))**2
      dsp = SQRT(arg1)
      dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
      ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
      sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
      psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
      dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip-dsio))
      dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
      dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
      psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
      pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
      psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
      dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip-dsio))
      dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
      dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
    END DO
  END SUBROUTINE PSWLIN

!  Differentiation of ggcalc in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: dqdm qinvu bij dzdm aij gamu
!                dqdg
!   with respect to varying inputs: dste xte x y nx ny xp ante
!                aste yp alfa yte apanel
!*==GGCALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE GGCALC_D()
    USE M_XSOLVE_DIFF, ONLY : ludcmp, ludcmp_d, baksub, baksub_d
    USE M_XUTILS_DIFF, ONLY : atanc, atanc_d
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: abis, ag1, ag2, bwt, cbis, ds1, ds2, dsmin, psi, psiinf, &
&   psi_n, qbis, res, res1, res2, sbis, xbis, ybis
    REAL :: abisd, ag1d, ag2d, cbisd, ds1d, ds2d, dsmind, res1d, res2d, &
&   sbisd, xbisd, ybisd
    REAL :: nxbis
    REAL :: nxbisd
    INTEGER :: i, j, k
    REAL, DIMENSION(iqx) :: bcol
    REAL, DIMENSION(iqx) :: bcold
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC ATAN2
    INTRINSIC SQRT
    INTRINSIC MIN
    REAL :: arg1
    REAL :: arg1d
    REAL :: temp
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!--------------------------------------------------------------
!     Calculates two surface vorticity (gamma) distributions
!     for alpha = 0, 90  degrees.  These are superimposed
!     in SPECAL or SPECCL for specified alpha or CL.
!--------------------------------------------------------------
!
!---- distance of internal control point ahead of sharp TE
!-    (fraction of smaller panel length adjacent to TE)
    bwt = 0.1
!
    IF (show_output) WRITE(*, *) &
&                    'Calculating unit vorticity distributions ...'
!
    DO i=1,n
      gam(i) = 0.
      gamu(i, 1) = 0.
      gamu(i, 2) = 0.
    END DO
    psio = 0.
    dqdmd = 0.0_8
    bijd = 0.0_8
    dzdgd = 0.0_8
    dzdmd = 0.0_8
    aijd = 0.0_8
    gamud = 0.0_8
    dqdgd = 0.0_8
!
!---- Set up matrix system for  Psi = Psio  on airfoil surface.
!-    The unknowns are (dGamma)i and dPsio.
    DO i=1,n
!
!------ calculate Psi and dPsi/dGamma array for current node
      CALL PSILIN_D(i, x(i), xd(i), y(i), yd(i), nx(i), nxd(i), ny(i), &
&             nyd(i), psi, psi_n, .false., .true.)
!
      psiinf = qinf*(COS(alfa)*y(i)-SIN(alfa)*x(i))
!
!------ RES1 = PSI( 0) - PSIO
!------ RES2 = PSI(90) - PSIO
      res1d = qinf*yd(i)
      res1 = qinf*y(i)
      res2d = -(qinf*xd(i))
      res2 = -(qinf*x(i))
!
!------ dRes/dGamma
      DO j=1,n
        aijd(i, j) = dzdgd(j)
        aij(i, j) = dzdg(j)
      END DO
!
      DO j=1,n
        bijd(i, j) = -dzdmd(j)
        bij(i, j) = -dzdm(j)
      END DO
!
!------ dRes/dPsio
      aijd(i, n+1) = 0.0_8
      aij(i, n+1) = -1.0
!
      gamud(i, 1) = -res1d
      gamu(i, 1) = -res1
      gamud(i, 2) = -res2d
      gamu(i, 2) = -res2
    END DO
!
!
!---- set Kutta condition
!-    RES = GAM(1) + GAM(N)
    res = 0.
!
    DO j=1,n+1
      aijd(n+1, j) = 0.0_8
      aij(n+1, j) = 0.0
    END DO
!
    aijd(n+1, 1) = 0.0_8
    aij(n+1, 1) = 1.0
    aijd(n+1, n) = 0.0_8
    aij(n+1, n) = 1.0
!
    gamud(n+1, 1) = 0.0_8
    gamu(n+1, 1) = -res
    gamud(n+1, 2) = 0.0_8
    gamu(n+1, 2) = -res
!
!---- set up Kutta condition (no direct source influence)
    DO j=1,n
      bijd(n+1, j) = 0.0_8
      bij(n+1, j) = 0.
    END DO
!
    IF (sharp) THEN
!----- set zero internal velocity in TE corner
!
!----- set TE bisector angle
      ag1d = xp(1)*ypd(1)/((-yp(1))**2+(-xp(1))**2) - yp(1)*xpd(1)/((-yp&
&       (1))**2+(-xp(1))**2)
      ag1 = ATAN2(-yp(1), -xp(1))
      ag2d = ATANC_D(yp(n), ypd(n), xp(n), xpd(n), ag1, ag1d, ag2)
      abisd = 0.5*(ag1d+ag2d)
      abis = 0.5*(ag1+ag2)
      cbisd = -(SIN(abis)*abisd)
      cbis = COS(abis)
      sbisd = COS(abis)*abisd
      sbis = SIN(abis)
!
!----- minimum panel length adjacent to TE
      arg1d = 2*(x(1)-x(2))*(xd(1)-xd(2)) + 2*(y(1)-y(2))*(yd(1)-yd(2))
      arg1 = (x(1)-x(2))**2 + (y(1)-y(2))**2
      temp = SQRT(arg1)
      IF (arg1 .EQ. 0.0_8) THEN
        ds1d = 0.0_8
      ELSE
        ds1d = arg1d/(2.0*temp)
      END IF
      ds1 = temp
      arg1d = 2*(x(n)-x(n-1))*(xd(n)-xd(n-1)) + 2*(y(n)-y(n-1))*(yd(n)-&
&       yd(n-1))
      arg1 = (x(n)-x(n-1))**2 + (y(n)-y(n-1))**2
      temp = SQRT(arg1)
      IF (arg1 .EQ. 0.0_8) THEN
        ds2d = 0.0_8
      ELSE
        ds2d = arg1d/(2.0*temp)
      END IF
      ds2 = temp
      IF (ds1 .GT. ds2) THEN
        dsmind = ds2d
        dsmin = ds2
      ELSE
        dsmind = ds1d
        dsmin = ds1
      END IF
!
!----- control point on bisector just ahead of TE point
      xbisd = xted - bwt*(cbis*dsmind+dsmin*cbisd)
      xbis = xte - bwt*dsmin*cbis
      ybisd = yted - bwt*(sbis*dsmind+dsmin*sbisd)
      ybis = yte - bwt*dsmin*sbis
!cc       write(*,*) xbis, ybis
!
!----- set velocity component along bisector line
! XFOILAD: normal passed through a variable (an expression argument
! becomes an undeclared temporary in Tapenade's split reverse code)
      nxbisd = -sbisd
      nxbis = -sbis
      dzdgd = 0.0_8
      CALL PSILIN_D(0, xbis, xbisd, ybis, ybisd, nxbis, nxbisd, cbis, &
&             cbisd, psi, qbis, .false., .true.)
!
!CC--- RES = DQDGj*Gammaj + DQDMj*Massj + QINF*(COSA*CBIS + SINA*SBIS)
      res = qbis
!
!----- dRes/dGamma
      DO j=1,n
        aijd(n, j) = dqdgd(j)
        aij(n, j) = dqdg(j)
      END DO
!
!----- -dRes/dMass
      DO j=1,n
        bijd(n, j) = -dqdmd(j)
        bij(n, j) = -dqdm(j)
      END DO
!
!----- dRes/dPsio
      aijd(n, n+1) = 0.0_8
      aij(n, n+1) = 0.
!
!----- -dRes/dUinf
      gamud(n, 1) = -cbisd
      gamu(n, 1) = -cbis
!
!----- -dRes/dVinf
      gamud(n, 2) = -sbisd
      gamu(n, 2) = -sbis
!
    END IF
!
!---- LU-factor coefficient matrix AIJ
    CALL LUDCMP_D(iqx, n + 1, aij, aijd, aijpiv)
    lqaij = .true.
    bcold = 0.0_8
!
!---- solve system for the two vorticity distributions
! XFOILAD: columns are copied to a work vector instead of being passed
! by sequence association (BIJ(1,j), GAMU(1,k)): Tapenade otherwise
! pushes/pops IQX*IZX values from that address and overruns the array.
    DO k=1,2
      DO i=1,iqx
        bcold(i) = gamud(i, k)
        bcol(i) = gamu(i, k)
      END DO
      CALL BAKSUB_D(iqx, n + 1, aij, aijd, aijpiv, bcol, bcold)
      DO i=1,iqx
        gamud(i, k) = bcold(i)
        gamu(i, k) = bcol(i)
      END DO
    END DO
    qinvud = 0.0_8
!
!---- set inviscid alpha=0,90 surface speeds for this geometry
    DO i=1,n
      qinvud(i, 1) = gamud(i, 1)
      qinvu(i, 1) = gamu(i, 1)
      qinvud(i, 2) = gamud(i, 2)
      qinvu(i, 2) = gamu(i, 2)
    END DO
!
    lgamu = .true.
  END SUBROUTINE GGCALC_D

