!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------
!     Calculates source panel influence coefficient
!     matrix for current airfoil and wake geometry.
!-----------------------------------------------------
!
    IF (show_output) WRITE(*, *) &
&                    'Calculating source influence matrix ...'
!
    IF (.NOT.ladij) THEN
      dijd = 0.0_8
      bcold = 0.0_8
!
!----- calculate source influence matrix for airfoil surface if it doesn't exist
      DO j=1,n
!
!------- multiply each dPsi/Sig vector by inverse of factored dPsi/dGam matrix
        DO k=1,iqx
          bcold(k) = bijd(k, j)
          bcol(k) = bij(k, j)
        END DO
        CALL BAKSUB_D(iqx, n + 1, aij, aijd, aijpiv, bcol, bcold)
        DO k=1,iqx
          bijd(k, j) = bcold(k)
          bij(k, j) = bcol(k)
        END DO
!
!------- store resulting dGam/dSig = dQtan/dSig vector
        DO i=1,n
          dijd(i, j) = bijd(i, j)
          dij(i, j) = bij(i, j)
        END DO
      END DO
!
      ladij = .true.
!
    ELSE
      dijd = 0.0_8
      bcold = 0.0_8
    END IF
!
!---- set up coefficient matrix of dPsi/dm on airfoil surface
    DO i=1,n
      CALL PSWLIN_D(i, x(i), xd(i), y(i), yd(i), nx(i), nxd(i), ny(i), &
&             nyd(i), psi, psi_n)
      DO j=n+1,n+nw
        bijd(i, j) = -dzdmd(j)
        bij(i, j) = -dzdm(j)
      END DO
    END DO
!
!---- set up Kutta condition (no direct source influence)
    DO j=n+1,n+nw
      bijd(n+1, j) = 0.0_8
      bij(n+1, j) = 0.
    END DO
!
!---- sharp TE gamma extrapolation also has no source influence
    IF (sharp) THEN
      DO j=n+1,n+nw
        bijd(n, j) = 0.0_8
        bij(n, j) = 0.
      END DO
    END IF
!
!---- multiply by inverse of factored dPsi/dGam matrix
    DO j=n+1,n+nw
      DO k=1,iqx
        bcold(k) = bijd(k, j)
        bcol(k) = bij(k, j)
      END DO
      CALL BAKSUB_D(iqx, n + 1, aij, aijd, aijpiv, bcol, bcold)
      DO k=1,iqx
        bijd(k, j) = bcold(k)
        bij(k, j) = bcol(k)
      END DO
    END DO
!
!---- set the source influence matrix for the wake sources
    DO i=1,n
      DO j=n+1,n+nw
        dijd(i, j) = bijd(i, j)
        dij(i, j) = bij(i, j)
      END DO
    END DO
    cijd = 0.0_8
!
!**** Now we need to calculate the influence of sources on the wake velocities
!
!---- calculcate dQtan/dGam and dQtan/dSig at the wake points
    DO i=n+1,n+nw
!
      iw = i - n
!
!------ airfoil contribution at wake panel node
      gamud = 0.0_8
      dzdmd = 0.0_8
      dzdgd = 0.0_8
      CALL PSILIN_D(i, x(i), xd(i), y(i), yd(i), nx(i), nxd(i), ny(i), &
&             nyd(i), psi, psi_n, .false., .true.)
!
      DO j=1,n
        cijd(iw, j) = dqdgd(j)
        cij(iw, j) = dqdg(j)
      END DO
!
      DO j=1,n
        dijd(i, j) = dqdmd(j)
        dij(i, j) = dqdm(j)
      END DO
!
!------ wake contribution
      dzdmd = 0.0_8
      CALL PSWLIN_D(i, x(i), xd(i), y(i), yd(i), nx(i), nxd(i), ny(i), &
&             nyd(i), psi, psi_n)
!
      DO j=n+1,n+nw
        dijd(i, j) = dqdmd(j)
        dij(i, j) = dqdm(j)
      END DO
    END DO
!
!
!---- add on effect of all sources on airfoil vorticity which effects wake Qtan
    DO i=n+1,n+nw
      iw = i - n
!
!------ airfoil surface source contribution first
      DO j=1,n
        sum = 0.
        sumd = 0.0_8
        DO k=1,n
          sumd = sumd + dij(k, j)*cijd(iw, k) + cij(iw, k)*dijd(k, j)
          sum = sum + cij(iw, k)*dij(k, j)
        END DO
        dijd(i, j) = dijd(i, j) + sumd
        dij(i, j) = dij(i, j) + sum
      END DO
!
!------ wake source contribution next
      DO j=n+1,n+nw
        sum = 0.
        sumd = 0.0_8
        DO k=1,n
          sumd = sumd + bij(k, j)*cijd(iw, k) + cij(iw, k)*bijd(k, j)
          sum = sum + cij(iw, k)*bij(k, j)
        END DO
        dijd(i, j) = dijd(i, j) + sumd
        dij(i, j) = dij(i, j) + sum
      END DO
    END DO
!
!
!---- make sure first wake point has same velocity as trailing edge
    DO j=1,n+nw
      dijd(n+1, j) = dijd(n, j)
      dij(n+1, j) = dij(n, j)
    END DO
!
    lwdij = .true.
  END SUBROUTINE QDCALC_D

!*==QDCALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE QDCALC()
    USE M_XSOLVE_DIFF, ONLY : baksub
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i, iw, j, k
    REAL, DIMENSION(iqx) :: bcol
    REAL :: psi, psi_n, sum
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------
!     Calculates source panel influence coefficient
!     matrix for current airfoil and wake geometry.
!-----------------------------------------------------
!
    IF (show_output) WRITE(*, *) &
&                    'Calculating source influence matrix ...'
!
    IF (.NOT.ladij) THEN
!
!----- calculate source influence matrix for airfoil surface if it doesn't exist
      DO j=1,n
!
!------- multiply each dPsi/Sig vector by inverse of factored dPsi/dGam matrix
        DO k=1,iqx
          bcol(k) = bij(k, j)
        END DO
        CALL BAKSUB(iqx, n + 1, aij, aijpiv, bcol)
        DO k=1,iqx
          bij(k, j) = bcol(k)
        END DO
!
!------- store resulting dGam/dSig = dQtan/dSig vector
        DO i=1,n
          dij(i, j) = bij(i, j)
        END DO
      END DO
!
      ladij = .true.
!
    END IF
!
!---- set up coefficient matrix of dPsi/dm on airfoil surface
    DO i=1,n
      CALL PSWLIN(i, x(i), y(i), nx(i), ny(i), psi, psi_n)
      DO j=n+1,n+nw
        bij(i, j) = -dzdm(j)
      END DO
    END DO
!
!---- set up Kutta condition (no direct source influence)
    DO j=n+1,n+nw
      bij(n+1, j) = 0.
    END DO
!
!---- sharp TE gamma extrapolation also has no source influence
    IF (sharp) THEN
      DO j=n+1,n+nw
        bij(n, j) = 0.
      END DO
    END IF
!
!---- multiply by inverse of factored dPsi/dGam matrix
    DO j=n+1,n+nw
      DO k=1,iqx
        bcol(k) = bij(k, j)
      END DO
      CALL BAKSUB(iqx, n + 1, aij, aijpiv, bcol)
      DO k=1,iqx
        bij(k, j) = bcol(k)
      END DO
    END DO
!
!---- set the source influence matrix for the wake sources
    DO i=1,n
      DO j=n+1,n+nw
        dij(i, j) = bij(i, j)
      END DO
    END DO
!
!**** Now we need to calculate the influence of sources on the wake velocities
!
!---- calculcate dQtan/dGam and dQtan/dSig at the wake points
    DO i=n+1,n+nw
!
      iw = i - n
!
!------ airfoil contribution at wake panel node
      CALL PSILIN(i, x(i), y(i), nx(i), ny(i), psi, psi_n, .false., &
&           .true.)
!
      DO j=1,n
        cij(iw, j) = dqdg(j)
      END DO
!
      DO j=1,n
        dij(i, j) = dqdm(j)
      END DO
!
!------ wake contribution
      CALL PSWLIN(i, x(i), y(i), nx(i), ny(i), psi, psi_n)
!
      DO j=n+1,n+nw
        dij(i, j) = dqdm(j)
      END DO
    END DO
!
!
!---- add on effect of all sources on airfoil vorticity which effects wake Qtan
    DO i=n+1,n+nw
      iw = i - n
!
!------ airfoil surface source contribution first
      DO j=1,n
        sum = 0.
        DO k=1,n
          sum = sum + cij(iw, k)*dij(k, j)
        END DO
        dij(i, j) = dij(i, j) + sum
      END DO
!
!------ wake source contribution next
      DO j=n+1,n+nw
        sum = 0.
        DO k=1,n
          sum = sum + cij(iw, k)*bij(k, j)
        END DO
        dij(i, j) = dij(i, j) + sum
      END DO
    END DO
!
!
!---- make sure first wake point has same velocity as trailing edge
    DO j=1,n+nw
      dij(n+1, j) = dij(n, j)
    END DO
!
    lwdij = .true.
  END SUBROUTINE QDCALC

!  Differentiation of xywake in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: dqdm s xte x y nx ny dzdm yte
!                apanel dqdg
!   with respect to varying inputs: dqdm dste s x y nx ny xp ante
!                aste chord dzdm yp alfa apanel dqdg gam
!*==XYWAKE.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE XYWAKE_D()
    USE M_XUTILS_DIFF, ONLY : setexp, setexp_d
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: ds, ds1, psi, psi_x, psi_y, smod, sx, sy
    REAL :: dsd, ds1d, psi_xd, psi_yd, smodd, sxd, syd
    INTEGER :: i
    REAL, DIMENSION(iwx) :: snw
    REAL, DIMENSION(iwx) :: snwd
    INTRINSIC INT
    INTRINSIC SQRT
    INTRINSIC ATAN2
    REAL :: arg1
    REAL :: arg1d
    REAL :: result1
    REAL :: result1d
    REAL :: temp
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------
!     Sets wake coordinate array for current surface
!     vorticity and/or mass source distributions.
!-----------------------------------------------------
!
    IF (show_output) WRITE(*, *) 'Calculating wake trajectory ...'
!
!---- number of wake points
    nw = n/12 + 10*INT(waklen)
    IF (nw .GT. iwx) THEN
      IF (show_output) WRITE(*, *) &
&          'Array size (IWX) too small.  Last wake point index reduced.'
      nw = iwx
    END IF
!
    ds1d = 0.5*(sd(2)-sd(1)+sd(n)-sd(n-1))
    ds1 = 0.5*(s(2)-s(1)+s(n)-s(n-1))
! XFOILAD: work vector instead of SNEW(N+1) (sequence association, see QDCALC)
    CALL SETEXP_D(snw, snwd, ds1, ds1d, waklen*chord, waklen*chordd, nw)
    snewd = 0.0_8
    DO i=1,nw
      snewd(n+i) = snwd(i)
      snew(n+i) = snw(i)
    END DO
!
!      write(*,*) waklen, chord, waklen*chord
!      write(*,*) ds1
!      do i = n+1, n+nw
!        write(*,*) i-n, snew(i)
!      enddo
    xted = 0.5*(xd(1)+xd(n))
    xte = 0.5*(x(1)+x(n))
    yted = 0.5*(yd(1)+yd(n))
    yte = 0.5*(y(1)+y(n))
!
!---- set first wake point a tiny distance behind TE
    i = n + 1
    sxd = 0.5*(ypd(n)-ypd(1))
    sx = 0.5*(yp(n)-yp(1))
    syd = 0.5*(xpd(1)-xpd(n))
    sy = 0.5*(xp(1)-xp(n))
    arg1d = 2*sx*sxd + 2*sy*syd
    arg1 = sx**2 + sy**2
    temp = SQRT(arg1)
    IF (arg1 .EQ. 0.0_8) THEN
      smodd = 0.0_8
    ELSE
      smodd = arg1d/(2.0*temp)
    END IF
    smod = temp
    nxd(i) = (sxd-sx*smodd/smod)/smod
    nx(i) = sx/smod
    nyd(i) = (syd-sy*smodd/smod)/smod
    ny(i) = sy/smod
    xd(i) = xted - 0.0001*nyd(i)
    x(i) = xte - 0.0001*ny(i)
    yd(i) = yted + 0.0001*nxd(i)
    y(i) = yte + 0.0001*nx(i)
    sd(i) = sd(n)
    s(i) = s(n)
!
!---- calculate streamfunction gradient components at first point
    CALL PSILIN_XW_D(i, x(i), xd(i), y(i), yd(i), 1.0, 0.0, psi, psi_x, &
&              psi_xd, .false., .false.)
    CALL PSILIN_XW_D(i, x(i), xd(i), y(i), yd(i), 0.0, 1.0, psi, psi_y, &
&              psi_yd, .false., .false.)
!
!---- set unit vector normal to wake at first point
    arg1d = 2*psi_x*psi_xd + 2*psi_y*psi_yd
    arg1 = psi_x**2 + psi_y**2
    temp = SQRT(arg1)
    IF (arg1 .EQ. 0.0_8) THEN
      result1d = 0.0_8
    ELSE
      result1d = arg1d/(2.0*temp)
    END IF
    result1 = temp
    nxd(i+1) = -((psi_xd-psi_x*result1d/result1)/result1)
    nx(i+1) = -(psi_x/result1)
    arg1d = 2*psi_x*psi_xd + 2*psi_y*psi_yd
    arg1 = psi_x**2 + psi_y**2
    temp = SQRT(arg1)
    IF (arg1 .EQ. 0.0_8) THEN
      result1d = 0.0_8
    ELSE
      result1d = arg1d/(2.0*temp)
    END IF
    result1 = temp
    nyd(i+1) = -((psi_yd-psi_y*result1d/result1)/result1)
    ny(i+1) = -(psi_y/result1)
!
!---- set angle of wake panel normal
    apaneld(i) = psi_x*psi_yd/(psi_y**2+psi_x**2) - psi_y*psi_xd/(psi_y&
&     **2+psi_x**2)
    apanel(i) = ATAN2(psi_y, psi_x)
!
!---- set rest of wake points
    DO i=n+2,n+nw
      dsd = snewd(i) - snewd(i-1)
      ds = snew(i) - snew(i-1)
!
!------ set new point DS downstream of last point
      xd(i) = xd(i-1) - ny(i)*dsd - ds*nyd(i)
      x(i) = x(i-1) - ds*ny(i)
      yd(i) = yd(i-1) + nx(i)*dsd + ds*nxd(i)
      y(i) = y(i-1) + ds*nx(i)
      sd(i) = sd(i-1) + dsd
      s(i) = s(i-1) + ds
!
      IF (i .NE. n + nw) THEN
!
!------- calculate normal vector for next point
        CALL PSILIN_XW_D(i, x(i), xd(i), y(i), yd(i), 1.0, 0.0, psi, &
&                  psi_x, psi_xd, .false., .false.)
        CALL PSILIN_XW_D(i, x(i), xd(i), y(i), yd(i), 0.0, 1.0, psi, &
&                  psi_y, psi_yd, .false., .false.)
!
        arg1d = 2*psi_x*psi_xd + 2*psi_y*psi_yd
        arg1 = psi_x**2 + psi_y**2
        temp = SQRT(arg1)
        IF (arg1 .EQ. 0.0_8) THEN
          result1d = 0.0_8
        ELSE
          result1d = arg1d/(2.0*temp)
        END IF
        result1 = temp
        nxd(i+1) = -((psi_xd-psi_x*result1d/result1)/result1)
        nx(i+1) = -(psi_x/result1)
        arg1d = 2*psi_x*psi_xd + 2*psi_y*psi_yd
        arg1 = psi_x**2 + psi_y**2
        temp = SQRT(arg1)
        IF (arg1 .EQ. 0.0_8) THEN
          result1d = 0.0_8
        ELSE
          result1d = arg1d/(2.0*temp)
        END IF
        result1 = temp
        nyd(i+1) = -((psi_yd-psi_y*result1d/result1)/result1)
        ny(i+1) = -(psi_y/result1)
!
!------- set angle of wake panel normal
        apaneld(i) = psi_x*psi_yd/(psi_y**2+psi_x**2) - psi_y*psi_xd/(&
&         psi_y**2+psi_x**2)
        apanel(i) = ATAN2(psi_y, psi_x)
      END IF
    END DO
!
!
!---- set wake presence flag and corresponding alpha
    lwake = .true.
    awake = alfa
!
!---- old source influence matrix is invalid for the new wake geometry
    lwdij = .false.
  END SUBROUTINE XYWAKE_D

