!  Differentiation of stfind in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: sst_go sst_gp sst
!   with respect to varying inputs: s gam
!*==STFIND.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE STFIND_D()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dgam, ds
    REAL :: dgamd, dsd
    INTEGER :: i
    REAL :: temp
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------
!     Locates stagnation point arc length
!     location SST and panel index IST.
!-----------------------------------------
!
    DO i=1,n-1
      IF (gam(i) .GE. 0.0 .AND. gam(i+1) .LT. 0.0) GOTO 100
    END DO
!
    IF (show_output) WRITE(*, *) &
&                   'STFIND: Stagnation point not found. Continuing ...'
    i = n/2
!
!
 100 ist = i
    dgamd = gamd(i+1) - gamd(i)
    dgam = gam(i+1) - gam(i)
    dsd = sd(i+1) - sd(i)
    ds = s(i+1) - s(i)
!
!---- evaluate so as to minimize roundoff for very small GAM(I) or GAM(I+1)
    IF (gam(i) .LT. -gam(i+1)) THEN
      temp = ds/dgam
      sstd = sd(i) - temp*gamd(i) - gam(i)*(dsd-temp*dgamd)/dgam
      sst = s(i) - gam(i)*temp
    ELSE
      temp = ds/dgam
      sstd = sd(i+1) - temp*gamd(i+1) - gam(i+1)*(dsd-temp*dgamd)/dgam
      sst = s(i+1) - gam(i+1)*temp
    END IF
!
    temp = (sst-s(i+1))/dgam
    sst_god = (sstd-sd(i+1)-temp*dgamd)/dgam
    sst_go = temp
    temp = (s(i)-sst)/dgam
    sst_gpd = (sd(i)-sstd-temp*dgamd)/dgam
    sst_gp = temp
!
!---- XFOILAD: keep the stagnation point at least STFRAC panel lengths from
!     both nodes.  When it falls (nearly) on a node, e.g. a symmetric section
!     at alpha = 0 with a node at the LE, the first BL station of one side is
!     at xi ~ 0 with Ue ~ 0, and the similarity station makes the Newton system
!     singular (XFOIL's original tweak moved it by only 1e-7).  The clamped
!     stagnation point no longer depends on GAM.
    IF (sst .LT. s(i) + stfrac*ds) THEN
      sstd = sd(i) + stfrac*dsd
      sst = s(i) + stfrac*ds
      sst_go = 0.
      sst_gp = 0.
      sst_god = 0.0_8
      sst_gpd = 0.0_8
    END IF
    IF (sst .GT. s(i+1) - stfrac*ds) THEN
      sstd = sd(i+1) - stfrac*dsd
      sst = s(i+1) - stfrac*ds
      sst_go = 0.
      sst_gp = 0.
      sst_god = 0.0_8
      sst_gpd = 0.0_8
    END IF
  END SUBROUTINE STFIND_D

!*==STFIND.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE STFIND()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dgam, ds
    INTEGER :: i
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------
!     Locates stagnation point arc length
!     location SST and panel index IST.
!-----------------------------------------
!
    DO i=1,n-1
      IF (gam(i) .GE. 0.0 .AND. gam(i+1) .LT. 0.0) GOTO 100
    END DO
!
    IF (show_output) WRITE(*, *) &
&                   'STFIND: Stagnation point not found. Continuing ...'
    i = n/2
!
!
 100 ist = i
    dgam = gam(i+1) - gam(i)
    ds = s(i+1) - s(i)
!
!---- evaluate so as to minimize roundoff for very small GAM(I) or GAM(I+1)
    IF (gam(i) .LT. -gam(i+1)) THEN
      sst = s(i) - ds*(gam(i)/dgam)
    ELSE
      sst = s(i+1) - ds*(gam(i+1)/dgam)
    END IF
!
    sst_go = (sst-s(i+1))/dgam
    sst_gp = (s(i)-sst)/dgam
!
!---- XFOILAD: keep the stagnation point at least STFRAC panel lengths from
!     both nodes.  When it falls (nearly) on a node, e.g. a symmetric section
!     at alpha = 0 with a node at the LE, the first BL station of one side is
!     at xi ~ 0 with Ue ~ 0, and the similarity station makes the Newton system
!     singular (XFOIL's original tweak moved it by only 1e-7).  The clamped
!     stagnation point no longer depends on GAM.
    IF (sst .LT. s(i) + stfrac*ds) THEN
      sst = s(i) + stfrac*ds
      sst_go = 0.
      sst_gp = 0.
    END IF
    IF (sst .GT. s(i+1) - stfrac*ds) THEN
      sst = s(i+1) - stfrac*ds
      sst_go = 0.
      sst_gp = 0.
    END IF
  END SUBROUTINE STFIND

!*==IBLPAN.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE IBLPAN()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i, ibl, iblmax, is, iw
    INTRINSIC MAX
    INTEGER :: max1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------------
!     Sets  BL location -> panel location  pointer array IPAN
!-------------------------------------------------------------
!
!---- top surface first
    is = 1
!
    ibl = 1
    DO i=ist,1,-1
      ibl = ibl + 1
      ipan(ibl, is) = i
      vti(ibl, is) = 1.0
    END DO
!
    iblte(is) = ibl
    nbl(is) = ibl
!
!---- bottom surface next
    is = 2
!
    ibl = 1
    DO i=ist+1,n
      ibl = ibl + 1
      ipan(ibl, is) = i
      vti(ibl, is) = -1.0
    END DO
!
!---- wake
    iblte(is) = ibl
!
    DO iw=1,nw
      i = n + iw
      ibl = iblte(is) + iw
      ipan(ibl, is) = i
      vti(ibl, is) = -1.0
    END DO
!
    nbl(is) = iblte(is) + nw
!
!---- upper wake pointers (for plotting only)
    DO iw=1,nw
      ipan(iblte(1)+iw, 1) = ipan(iblte(2)+iw, 2)
      vti(iblte(1)+iw, 1) = 1.0
    END DO
    IF (iblte(1) .LT. iblte(2)) THEN
      max1 = iblte(2)
    ELSE
      max1 = iblte(1)
    END IF
!
!
    iblmax = max1 + nw
    IF (iblmax .GT. ivx) THEN
      IF (show_output) THEN
        WRITE(*, *) ' ***  BL array overflow.'
        WRITE(*, *) ' ***  Increase IVX to at least', iblmax
      END IF
      STOP
    ELSE
!
      lipan = .true.
    END IF
  END SUBROUTINE IBLPAN

!  Differentiation of xicalc in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: xssi wgap
!   with respect to varying inputs: xssi s x y wgap xp ante yp
!                sst
!*==XICALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE XICALC_D()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: aa, bb, crosp, dwdxte, dxssi, telrat, xeps, zn
    REAL :: aad, bbd, crospd, dwdxted, dxssid, xepsd, znd
    INTEGER :: i, ibl, ibl1, ibl2, is, is1, is2, iw
    REAL, SAVE :: xfeps
    INTRINSIC MAX
    INTRINSIC SQRT
    INTRINSIC MIN
    REAL :: arg1
    REAL :: arg1d
    REAL :: result1
    REAL :: result1d
    REAL :: temp
    REAL :: temp0
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------------
!     Sets BL arc length array on each airfoil side and wake
!-------------------------------------------------------------
    DATA xfeps /1.0e-7/
!
!---- minimum xi node arc length near stagnation point
    xepsd = xfeps*(sd(n)-sd(1))
    xeps = xfeps*(s(n)-s(1))
!
    is = 1
!
    xssid(1, is) = 0.0_8
    xssi(1, is) = 0.
!
    DO ibl=2,iblte(is)
      i = ipan(ibl, is)
      IF (sst - s(i) .LT. xeps) THEN
        xssid(ibl, is) = xepsd
        xssi(ibl, is) = xeps
      ELSE
        xssid(ibl, is) = sstd - sd(i)
        xssi(ibl, is) = sst - s(i)
      END IF
    END DO
!
!
    is = 2
!
    xssid(1, is) = 0.0_8
    xssi(1, is) = 0.
!
    DO ibl=2,iblte(is)
      i = ipan(ibl, is)
      IF (s(i) - sst .LT. xeps) THEN
        xssid(ibl, is) = xepsd
        xssi(ibl, is) = xeps
      ELSE
        xssid(ibl, is) = sd(i) - sstd
        xssi(ibl, is) = s(i) - sst
      END IF
    END DO
!
!
    is1 = 1
    is2 = 2
!
    ibl1 = iblte(is1) + 1
    xssid(ibl1, is1) = xssid(ibl1-1, is1)
    xssi(ibl1, is1) = xssi(ibl1-1, is1)
!
    ibl2 = iblte(is2) + 1
    xssid(ibl2, is2) = xssid(ibl2-1, is2)
    xssi(ibl2, is2) = xssi(ibl2-1, is2)
!
    DO ibl=iblte(is)+2,nbl(is)
      i = ipan(ibl, is)
      arg1d = 2*(x(i)-x(i-1))*(xd(i)-xd(i-1)) + 2*(y(i)-y(i-1))*(yd(i)-&
&       yd(i-1))
      arg1 = (x(i)-x(i-1))**2 + (y(i)-y(i-1))**2
      temp = SQRT(arg1)
      IF (arg1 .EQ. 0.0_8) THEN
        dxssid = 0.0_8
      ELSE
        dxssid = arg1d/(2.0*temp)
      END IF
      dxssi = temp
!
      ibl1 = iblte(is1) + ibl - iblte(is)
      ibl2 = iblte(is2) + ibl - iblte(is)
      xssid(ibl1, is1) = xssid(ibl1-1, is1) + dxssid
      xssi(ibl1, is1) = xssi(ibl1-1, is1) + dxssi
      xssid(ibl2, is2) = xssid(ibl2-1, is2) + dxssid
      xssi(ibl2, is2) = xssi(ibl2-1, is2) + dxssi
    END DO
!
!---- trailing edge flap length to TE gap ratio
    telrat = 2.50
!
!---- set up parameters for TE flap cubics
!
!cc   DWDXTE = YP(1)/XP(1) + YP(N)/XP(N)    !!! BUG  2/2/95
!
    temp = xp(n)*xp(n) + yp(n)*yp(n)
    temp0 = xp(1)*xp(1) + yp(1)*yp(1)
    arg1d = temp*(2*xp(1)*xpd(1)+2*yp(1)*ypd(1)) + temp0*(2*xp(n)*xpd(n)&
&     +2*yp(n)*ypd(n))
    arg1 = temp0*temp
    temp0 = SQRT(arg1)
    IF (arg1 .EQ. 0.0_8) THEN
      result1d = 0.0_8
    ELSE
      result1d = arg1d/(2.0*temp0)
    END IF
    result1 = temp0
    temp0 = (xp(1)*yp(n)-yp(1)*xp(n))/result1
    crospd = (yp(n)*xpd(1)+xp(1)*ypd(n)-xp(n)*ypd(1)-yp(1)*xpd(n)-temp0*&
&     result1d)/result1
    crosp = temp0
    arg1d = -(2*crosp*crospd)
    arg1 = 1.0 - crosp**2
    temp0 = SQRT(arg1)
    IF (arg1 .EQ. 0.0_8) THEN
      result1d = 0.0_8
    ELSE
      result1d = arg1d/(2.0*temp0)
    END IF
    result1 = temp0
    dwdxted = (crospd-crosp*result1d/result1)/result1
    dwdxte = crosp/result1
    IF (dwdxte .LT. -(3.0/telrat)) THEN
      dwdxte = -(3.0/telrat)
      dwdxted = 0.0_8
    ELSE
      dwdxte = dwdxte
    END IF
    IF (dwdxte .GT. 3.0/telrat) THEN
      dwdxte = 3.0/telrat
      dwdxted = 0.0_8
    ELSE
      dwdxte = dwdxte
    END IF
!
    aad = telrat*dwdxted
    aa = 3.0 + telrat*dwdxte
    bbd = -(telrat*dwdxted)
    bb = -2.0 - telrat*dwdxte
!
    IF (sharp) THEN
      DO iw=1,nw
        wgapd(iw) = 0.0_8
        wgap(iw) = 0.
      END DO
    ELSE
!----- set TE flap (wake gap) array
      is = 2
      DO iw=1,nw
        ibl = iblte(is) + iw
        temp0 = (xssi(ibl, is)-xssi(iblte(is), is))/(telrat*ante)
        znd = -((xssid(ibl, is)-xssid(iblte(is), is)-temp0*telrat*anted)&
&         /(telrat*ante))
        zn = 1.0 - temp0
        wgapd(iw) = 0.0_8
        wgap(iw) = 0.
        IF (zn .GE. 0.0) THEN
          temp0 = ante*(zn*zn)
          wgapd(iw) = temp0*(aad+zn*bbd+bb*znd) + (aa+bb*zn)*(zn**2*&
&           anted+ante*2*zn*znd)
          wgap(iw) = (aa+bb*zn)*temp0
        END IF
      END DO
    END IF
  END SUBROUTINE XICALC_D

