!
    DO ibl=2,iblte(is)
      i = ipan(ibl, is)
      IF (s(i) - sst .LT. xeps) THEN
        xssi(ibl, is) = xeps
      ELSE
        xssi(ibl, is) = s(i) - sst
      END IF
    END DO
!
!
    is1 = 1
    is2 = 2
!
    ibl1 = iblte(is1) + 1
    xssi(ibl1, is1) = xssi(ibl1-1, is1)
!
    ibl2 = iblte(is2) + 1
    xssi(ibl2, is2) = xssi(ibl2-1, is2)
!
    DO ibl=iblte(is)+2,nbl(is)
      i = ipan(ibl, is)
      arg1 = (x(i)-x(i-1))**2 + (y(i)-y(i-1))**2
      dxssi = SQRT(arg1)
