!*==QISET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE QISET_D()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i
    INTRINSIC COS
    INTRINSIC SIN
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------
!     Sets inviscid panel tangential velocity for
!     current alpha.
!-------------------------------------------------------
!
    cosad = -(SIN(alfa)*alfad)
    cosa = COS(alfa)
    sinad = COS(alfa)*alfad
    sina = SIN(alfa)
!
    DO i=1,n+nw
      qinvd(i) = qinvu(i, 1)*cosad + cosa*qinvud(i, 1) + qinvu(i, 2)*&
&       sinad + sina*qinvud(i, 2)
      qinv(i) = cosa*qinvu(i, 1) + sina*qinvu(i, 2)
      qinv_ad(i) = qinvu(i, 2)*cosad + cosa*qinvud(i, 2) - qinvu(i, 1)*&
&       sinad - sina*qinvud(i, 1)
      qinv_a(i) = -(sina*qinvu(i, 1)) + cosa*qinvu(i, 2)
    END DO
