!  Differentiation of ueset in forward (tangent) mode (with options r8 messagesInFile):
!   variations   of useful results: uedg
!   with respect to varying inputs: uedg mass dij uinv
!*==UESET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE UESET_D()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dui, ue_m
    REAL :: duid, ue_md
    INTEGER :: i, ibl, is, j, jbl, js
    REAL :: temp
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!---------------------------------------------------------
!     Sets Ue from inviscid Ue plus all source influence
!---------------------------------------------------------
!
    DO is=1,2
      DO ibl=2,nbl(is)
        i = ipan(ibl, is)
!
        dui = 0.
        duid = 0.0_8
        DO js=1,2
          DO jbl=2,nbl(js)
            j = ipan(jbl, js)
            temp = vti(ibl, is)*vti(jbl, js)
            ue_md = -(temp*dijd(i, j))
            ue_m = -(temp*dij(i, j))
            duid = duid + mass(jbl, js)*ue_md + ue_m*massd(jbl, js)
            dui = dui + ue_m*mass(jbl, js)
          END DO
        END DO
!
        uedgd(ibl, is) = uinvd(ibl, is) + duid
        uedg(ibl, is) = uinv(ibl, is) + dui
      END DO
    END DO
  END SUBROUTINE UESET_D

!*==UESET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE UESET()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
