!---------------------------------------------------------
!
    DO is=1,2
      DO ibl=2,nbl(is)
        i = ipan(ibl, is)
!
        dui = 0.
        DO js=1,2
          DO jbl=2,nbl(js)
            j = ipan(jbl, js)
            ue_m = -(vti(ibl, is)*vti(jbl, js)*dij(i, j))
            dui = dui + ue_m*mass(jbl, js)
          END DO
        END DO
!
        uedg(ibl, is) = uinv(ibl, is) + dui
      END DO
    END DO
